/* Keep authoring helpers local when loaded as a classic browser script. */
(function () {
/* A23: 80 frozen lemmas, audited in four exact 20-word checkpoints. */
'use strict';
const D = globalThis.RA.D;
const E = (origin, word) => ({origin, prefix:null, root:null, suffix:null, source:'Etymonline, https://www.etymonline.com/word/'+word.toLowerCase()});
const C = (senseId,domain,en,zh,structure,grammar,rationale) => ({senseId,domain,en,zh,structure,grammar,rationale,sourceType:'authored'});
const M = (wrong,right,reason,errorType='meaning') => ({wrong,right,reason,errorType});
const Q = (w,n,sense,prompt,options,answer,explain,errorType='meaning') => ({id:w+'.q'+n,senseId:w+'.s'+sense,errorType,type:'辨义与用法',prompt,options,answer,explain});
D('dementia',{etymology:E('Dementia came through French and Latin dementia, from Latin demens “out of one’s mind,” formed with de- and mens “mind.” It names a syndrome involving decline in memory and other cognitive abilities.','dementia'),contexts:[C('dementia.s1','临床照护','After repeated memory problems began to affect her shopping and cooking, a specialist assessed her for dementia and discussed support with the family.','反复出现的记忆问题开始影响她购物和做饭后，专科医生对她进行痴呆评估，并与家人讨论支持方案。','After repeated memory problems began to affect her shopping and cooking / a specialist assessed her for dementia / and discussed support with the family.','assess someone for dementia 表示评估是否存在痴呆相关状况。','认知问题需要临床评估；语境使用疾病综合征义 s1。'),C('dementia.s2','护理服务','The ward provides meals and orientation support for people living with dementia, including patients who become confused in unfamiliar surroundings.','病房为痴呆患者提供餐食和定向支持，包括在陌生环境中容易困惑的患者。','The ward provides meals and orientation support / for people living with dementia / including patients who become confused in unfamiliar surroundings.','people living with dementia 是以人为本的表达。','照护对象可表现为困惑和记忆问题，对应症状集合义 s2。')],mistakes:[M('Dementia is a normal, brief lapse in memory that disappears after a good night’s sleep.','A brief lapse in memory may follow poor sleep, but dementia is a serious syndrome involving persistent cognitive decline.','把短暂健忘直接等同于持续的认知衰退综合征，混淆了普通遗忘与医学概念。','confusable')],quiz:[Q('dementia',1,1,'Which situation most clearly calls for assessment for dementia?',['A persistent decline in memory and reasoning that disrupts daily life.','Forgetting one name once after a tiring day.','Choosing to learn a new language slowly.'],'A persistent decline in memory and reasoning that disrupts daily life.','Dementia involves ongoing cognitive decline, not an isolated everyday lapse.'),Q('dementia',2,2,'In a care setting, “people with dementia” may need support because they?',['experience symptoms such as confusion and memory loss','are simply choosing not to speak','have a contagious cold'],'experience symptoms such as confusion and memory loss','The symptom sense refers to the cluster that can include confusion and memory loss.'),Q('dementia',3,1,'Which statement uses dementia as a medical term?',['The clinic arranged a cognitive assessment after progressive memory changes.','The student called one forgotten password dementia.','The team used dementia to mean ordinary nervousness.'],'The clinic arranged a cognitive assessment after progressive memory changes.','Progressive cognitive changes are medically assessed; a single forgotten password is not dementia.'),Q('dementia',4,2,'A dementia-friendly ward is designed with which concern in mind?',['Patients may need clear cues because of memory or orientation difficulties.','Every patient is recovering from a broken bone.','Visitors must avoid all written signs.'],'Patients may need clear cues because of memory or orientation difficulties.','The symptom cluster can affect memory and orientation, so clear cues can help.') ]});
D('demerit',{etymology:E('Demerit is formed from de- “away, down” and merit, ultimately from Latin meritum “a thing deserved.” It can mean a fault or a recorded penalty.','demerit'),contexts:[C('demerit.s1','方案评估','The plan’s chief demerit is its high maintenance cost, although its low energy use remains a clear advantage.','该方案的主要缺点是维护成本高，尽管能耗低仍是明显优点。','The plan’s chief demerit is its high maintenance cost / although its low energy use remains a clear advantage.','demerit 与 merit 对举，表示缺点。','高维护成本是需要权衡的负面特征，对应 s1。'),C('demerit.s2','校规记录','Under the school’s published rules, a student who repeatedly skips detention may receive a demerit on the conduct record.','按照学校公布的规定，反复逃避留校处分的学生可能会在行为记录上被记一次过失分。','Under the school’s published rules / a student who repeatedly skips detention may receive a demerit / on the conduct record.','receive a demerit 表示被记一次违规扣分。','行为记录上的一次扣分是制度性处罚标记 s2。')],mistakes:[M('One demerit of the proposal was its reliable safety record and low repair cost.','One merit of the proposal was its reliable safety record and low repair cost.','可靠安全记录和低维修成本是优点，不是缺点；只需把 demerit 改为 merit。')],quiz:[Q('demerit',1,1,'Which is a demerit of a delivery system?',['It costs more to maintain than the alternatives.','It reaches every address on time.','It uses less fuel than expected.'],'It costs more to maintain than the alternatives.','A demerit is a disadvantage or fault.'),Q('demerit',2,2,'A school records a demerit after a rule is broken. What is it?',['a penalty mark','a prize for good work','a description of a building'],'a penalty mark','This sense is a formal mark against someone for misconduct.'),Q('demerit',3,1,'The report lists the merits and demerits of both designs. It compares their?',['advantages and disadvantages','authors and publication dates','colours only'],'advantages and disadvantages','Merits are advantages; demerits are drawbacks.'),Q('demerit',4,2,'Which event would most plausibly earn a student a demerit?',['Repeatedly breaking a stated conduct rule.','Helping a classmate without being asked.','Submitting an assignment early.'],'Repeatedly breaking a stated conduct rule.','A demerit is recorded for a rule violation or bad behaviour.') ]});
D('democrat',{etymology:E('Democrat is built from democracy with the agent suffix -at, ultimately combining Greek demos “people” and kratos “power, rule.” It can name an adherent of democracy or a member of the U.S. Democratic Party.','democrat'),contexts:[C('democrat.s1','政治理念','As a committed democrat, the mayor argued that citizens should choose their representatives through open elections.','作为坚定的民主主义者，市长主张公民应通过公开选举选择代表。','As a committed democrat / the mayor argued / that citizens should choose their representatives through open elections.','democrat 表示支持人民参与治理的民主主义者。','公开选举与民众选择代表直接体现民主理念义 s1。'),C('democrat.s2','美国政党','The Democrat won the district’s nomination after a close primary, then campaigned against the Republican candidate.','初选竞争激烈后，这位民主党人赢得了该选区的提名，随后与共和党候选人展开竞选。','The Democrat won the district’s nomination after a close primary / then campaigned against the Republican candidate.','美国政党名称语境中常大写 Democrat。','初选提名、共和党候选人明确标示美国民主党成员义 s2。')],mistakes:[M('In the U.S. election report, the Republican candidate was described as a Democrat despite belonging to the Republican Party.','In the U.S. election report, the Republican candidate was described as a Republican, not a Democrat.','此句把美国民主党成员称作共和党人，政党身份自相矛盾。','confusable')],quiz:[Q('democrat',1,1,'A democrat in the broad political sense supports?',['government in which the people have a voice','rule by an unelected hereditary monarch only','the removal of all public elections'],'government in which the people have a voice','The general sense is a believer in government by the people.'),Q('democrat',2,2,'In a U.S. election story, a Democrat is a member of?',['the Democratic Party','the Republican Party','the Supreme Court'],'the Democratic Party','With this capitalization and context, Democrat names a party member.'),Q('democrat',3,1,'Which person best fits the broad sense of democrat?',['An advocate of elected representatives and popular participation.','A person who opposes any public vote.','A private company’s accountant.'],'An advocate of elected representatives and popular participation.','This sense concerns belief in rule by the people.'),Q('democrat',4,2,'A report says “the Democrat defeated the Republican in the primary.” The capitalized noun identifies?',['a U.S. Democratic Party member','any person who likes democracy, regardless of party','a judge who ran the election'],'a U.S. Democratic Party member','The party contrast and capitalization indicate the U.S. party sense.') ]});
D('democratic',{etymology:E('Democratic is formed from democracy plus -ic; democracy came through French and Latin from Greek demokratia, from demos “people” and kratos “rule.”','democratic'),contexts:[C('democratic.s1','选举制度','The constitution requires a democratic election in which adult citizens can vote freely and the result is counted transparently.','宪法要求举行民主选举，成年公民可以自由投票，计票过程公开透明。','The constitution requires a democratic election / in which adult citizens can vote freely / and the result is counted transparently.','democratic 修饰 election，描述人民通过投票参与治理。','普遍投票权和透明选举体现民主制度义 s1。'),C('democratic.s2','团队管理','The director used a democratic style of management, inviting technicians and assistants to comment before the team chose a schedule.','主管采用民主平等的管理方式，在团队确定日程前邀请技术人员和助理发表意见。','The director used a democratic style of management / inviting technicians and assistants to comment / before the team chose a schedule.','democratic 可形容平等、征求意见的处事方式。','各岗位人员都能参与意见表达，对应平等作风义 s2。')],mistakes:[M('The committee called its decision-making democratic, but only the chair could speak and everyone else was forbidden to vote.','The committee called its decision-making authoritarian, because only the chair could speak and decide.','禁止其他人发言和投票的单方面决策，不符合民主参与或平等协商。')],quiz:[Q('democratic',1,1,'Which election is most clearly democratic?',['Eligible citizens vote freely and the count is transparent.','One official appoints every winner in secret.','Voters are barred from choosing any candidate.'],'Eligible citizens vote freely and the count is transparent.','Democratic government depends on people taking part in elections.'),Q('democratic',2,2,'A democratic discussion among coworkers is likely to?',['give team members an equal chance to offer views','let one person silence all others','exclude the staff who do the work'],'give team members an equal chance to offer views','The interpersonal sense suggests an equal, participatory style.'),Q('democratic',3,1,'The adjective democratic in “a democratic constitution” points to?',['political power involving the people','a product designed by a committee','a private family tradition'],'political power involving the people','The institutional sense relates to rule and participation by citizens.'),Q('democratic',4,2,'A manager asks every team member to help choose the meeting time. This is a?',['democratic approach','secret ballot fraud','hereditary appointment'],'democratic approach','Seeking participation from all team members illustrates the equal-style sense.') ]});
D('democratization',{etymology:E('Democratization is democratize plus -ation: democratize derives from democratic/democracy and denotes making institutions or access more democratic. British English also commonly spells it democratisation.','democratization'),contexts:[C('democratization.s1','制度改革','The democratization of local government gave residents a direct vote for council members and opened budget meetings to the public.','地方政府的民主化让居民可以直接选举议员，并向公众开放预算会议。','The democratization of local government / gave residents a direct vote for council members / and opened budget meetings to the public.','the democratization of + 领域表示该领域逐步引入更广泛的民主参与。','居民获得投票权且会议公开，说明治理参与范围扩大，对应 s1。')],mistakes:[M('The country’s democratization abolished elections and transferred all decisions to one unelected ruler.','The country’s authoritarian centralization abolished elections and transferred all decisions to one unelected ruler.','取消选举并集中到未经选举的统治者手中，属于集权化而非民主化。')],quiz:[Q('democratization',1,1,'A country’s democratization would most likely involve?',['widening public participation in choosing leaders','cancelling elections and silencing voters','limiting political rights to one family'],'widening public participation in choosing leaders','Democratization is the spread or introduction of democratic government.'),Q('democratization',2,1,'What does the democratization of online learning suggest?',['More people gain access to learning resources.','Only a small group can use the resources.','All courses are removed from the internet.'],'More people gain access to learning resources.','The term can extend beyond politics to wider access or participation.'),Q('democratization',3,1,'Which change is evidence of democratization in a town?',['Residents are allowed to vote directly on local representatives.','A public meeting is replaced by a ruler’s private order.','The town permanently bans public comment.'],'Residents are allowed to vote directly on local representatives.','Giving residents voting rights broadens democratic participation.'),Q('democratization',4,1,'Which spelling is also used in British English for the process?',['democratisation','democratizationed','democratisement'],'democratisation','The British spelling commonly uses -s- where American English uses -z-.') ]});
D('demographer',{etymology:E('Demographer is formed from demography plus the person suffix -er. Demography combines Greek demos “people” with -graphy “description or study.”','demographer'),contexts:[C('demographer.s1','人口预测','A demographer compared birth rates, deaths, and migration to estimate how many school places the region will need in ten years.','人口学家比较出生率、死亡和迁移情况，以估算该地区十年后需要多少学位。','A demographer compared birth rates, deaths, and migration / to estimate how many school places the region will need in ten years.','demographer 指研究人口规模、组成和变化的专业人员。','出生、死亡和迁移是人口学家分析的典型变量。')],mistakes:[M('The demographer forecast population growth by studying the chemical composition of distant stars.','The astronomer studied the chemical composition of distant stars; a demographer studies human populations.','分析恒星成分属于天文学，不是人口学家的研究对象。','confusable')],quiz:[Q('demographer',1,1,'Which research task belongs to a demographer?',['Projecting a city’s age structure from births, deaths, and migration.','Measuring the orbit of a comet.','Identifying the mineral content of a rock.'],'Projecting a city’s age structure from births, deaths, and migration.','Demographers study human populations and their changes.'),Q('demographer',2,1,'A demographer advising a school district would examine?',['how many children live in each area','the strength of a bridge cable','the grammar of an ancient poem'],'how many children live in each area','Population size and structure help forecast demand for school places.'),Q('demographer',3,1,'Which professional might estimate future demand for elder-care services using age data?',['a demographer','a volcanologist','a court reporter'],'a demographer','Age structure and population trends are demographic evidence.'),Q('demographer',4,1,'The suffix in demographer most directly marks?',['a person who studies or works in the field','a place where people live','a past action'],'a person who studies or works in the field','The -er ending forms the noun for a person associated with demography.') ]});
D('demography',{etymology:E('Demography combines Greek demos “people” and -graphy, from graphein “to write or describe”; the English word names the statistical study of populations.','demography'),contexts:[C('demography.s1','人口结构','Demography helps the health service plan clinics by showing how the population’s age structure and migration patterns are changing.','人口学通过呈现人口年龄结构和迁移模式的变化，帮助卫生部门规划诊所。','Demography helps the health service plan clinics / by showing how the population’s age structure and migration patterns are changing.','demography 作学科名词，关注人口规模、结构及变化。','年龄结构和迁移是研究人口变化的核心指标。')],mistakes:[M('Demography is the study of mineral crystals, their shapes, and the rocks in which they form.','Crystallography is the study of mineral crystals; demography is the statistical study of human populations.','矿物晶体研究属于晶体学，demography 研究人口。','confusable')],quiz:[Q('demography',1,1,'Which question is fundamentally demographic?',['How is a city’s population changing through births, deaths, and migration?','What is the chemical formula of quartz?','How do musicians tune a violin?'],'How is a city’s population changing through births, deaths, and migration?','Demography studies population size, structure, and change.'),Q('demography',2,1,'A report about the ageing population of a country belongs to?',['demography','botany','acoustics'],'demography','Age composition and population trends are demographic subjects.'),Q('demography',3,1,'What information would demography most directly provide to planners?',['the number and distribution of people by age','the boiling point of a metal','the spelling history of a verb'],'the number and distribution of people by age','Demographic analysis describes the size and structure of populations.'),Q('demography',4,1,'The second element -graphy in demography is associated with?',['description or study','a person who rules','a measurement of temperature'],'description or study','The word’s Greek element relates to writing or description, reflected in the name of the field.') ]});
D('demolition',{etymology:E('Demolition came through French démolition from Latin demolitio, from demoliri “pull down”; the verb combines de- with moliri “build or construct.”','demolition'),contexts:[C('demolition.s1','旧楼拆除','The demolition of the unsafe warehouse began after engineers removed the roof and fenced off the surrounding street.','工程师拆除屋顶并封闭周边街道后，这座不安全仓库开始拆除。','The demolition of the unsafe warehouse began / after engineers removed the roof / and fenced off the surrounding street.','demolition of a building 指有意拆毁建筑的过程。','拆屋顶、围起街道是建筑拆除作业。'),C('demolition.s2','论证批驳','Her demolition of the proposal was not a personal attack: she showed that its cost estimates ignored three major expenses.','她对该提案的彻底批驳并非人身攻击：她指出其成本估算漏掉了三项主要开支。','Her demolition of the proposal was not a personal attack / she showed that its cost estimates ignored three major expenses.','demolition 可比喻对论点或主张的彻底驳倒。','指出关键估算漏洞使提案站不住脚，体现比喻义 s2。')],mistakes:[M('The demolition of the old hall preserved every wall exactly as it was and involved no pulling down.','The renovation of the old hall preserved every wall exactly as it was and involved no pulling down.','完整保留建筑且不拆除，与 demolition 的拆毁含义冲突。')],quiz:[Q('demolition',1,1,'A city orders the demolition of a condemned factory. What will happen?',['The factory will be pulled down.','It will be painted and reopened unchanged.','It will be moved intact to another country.'],'The factory will be pulled down.','Literal demolition is the deliberate destruction of a building.'),Q('demolition',2,2,'A reviewer’s demolition of an argument means the reviewer?',['shows decisively why the argument fails','builds a new courtroom','quietly agrees with every claim'],'shows decisively why the argument fails','The figurative sense is complete destruction of an argument or idea.'),Q('demolition',3,1,'Which safety measure fits a building demolition?',['Fencing off the area before machinery begins work.','Inviting pedestrians to stand beneath the roof.','Removing all warning signs from the street.'],'Fencing off the area before machinery begins work.','A controlled demolition requires securing the area around the structure.'),Q('demolition',4,2,'“Her demolition of the rumour” most likely means she?',['disproved it thoroughly','constructed a building around it','repeated it without checking'],'disproved it thoroughly','Here demolition is metaphorical: the claim is convincingly dismantled.') ]});
D('demonstrative',{etymology:E('Demonstrative derives from demonstrate, from Latin demonstrare “point out, show,” with the adjective suffix -ive. It has an emotional sense and a sense of showing or pointing out.','demonstrative'),contexts:[C('demonstrative.s1','亲友情感','Although his family rarely hugged, he was demonstrative with his young daughter, openly praising her and holding her hand in public.','虽然他的家人很少拥抱彼此，但他会在女儿面前坦率表达感情，在公共场合夸奖她并牵着她的手。','Although his family rarely hugged / he was demonstrative with his young daughter / openly praising her and holding her hand in public.','be demonstrative with someone 表示对某人明显表达感情。','公开称赞和牵手是外露情感的表现，对应 s1。'),C('demonstrative.s2','语法指示词','In “those flowers are beautiful,” the word those is demonstrative because it points to particular flowers.','在“那些花很漂亮”中，those 是指示词，因为它指向特定的花。','In “those flowers are beautiful” / the word those is demonstrative / because it points to particular flowers.','语法术语中 demonstrative 可作名词性或形容词性成分，起指示作用。','those 指明说话人所指的特定花朵，符合 s2。')],mistakes:[M('He was demonstrative with his friends, carefully hiding all affection and refusing every kind word.','He was reserved with his friends, carefully hiding affection and refusing every kind word.','刻意隐藏感情、拒绝表达，与 demonstrative 的“感情外露”义相反。')],quiz:[Q('demonstrative',1,1,'A demonstrative person is likely to?',['show affection openly','hide every feeling from close friends','point only to objects in a diagram'],'show affection openly','The emotional sense means expressing feelings or affection freely.'),Q('demonstrative',2,2,'In “this book is mine,” this is a demonstrative because it?',['points to a particular book','expresses the speaker’s affection','describes a sound'],'points to a particular book','Demonstratives point out specific people or things.'),Q('demonstrative',3,1,'Which behaviour is most demonstrative?',['She openly hugs her sister and says she missed her.','She refuses to show any reaction to good news.','She labels a diagram with the word “this.”'],'She openly hugs her sister and says she missed her.','Open affection illustrates the emotional sense.'),Q('demonstrative',4,2,'Which word is demonstrative in “Those houses were built recently”?',['Those','built','recently'],'Those','Those points to a particular set of houses.') ]});
D('demonstrator',{etymology:E('Demonstrator comes from demonstrate, from Latin demonstrare “show, point out,” plus the agent suffix -or; it names a protest participant or someone who gives a practical demonstration.','demonstrator'),contexts:[C('demonstrator.s1','公共集会','A demonstrator held a sign outside the city hall, calling for the council to publish its air-quality data.','一名示威者在市政厅外举着标语，要求市议会公布空气质量数据。','A demonstrator held a sign outside the city hall / calling for the council to publish its air-quality data.','demonstrator 指参加公开抗议活动的人。','举标语并提出公共诉求明确体现示威者义 s1。'),C('demonstrator.s2','实验教学','The chemistry demonstrator showed the students how to connect the sensor before they carried out the experiment themselves.','化学实验指导员向学生演示如何连接传感器，然后学生再自行完成实验。','The chemistry demonstrator showed the students how to connect the sensor / before they carried out the experiment themselves.','英式大学语境中的 demonstrator 常指带领或协助实践课的教员。','演示实验设备使用方法，符合示范者/实验指导义 s2。')],mistakes:[M('The demonstrator at the laboratory marched in a street protest solely because she was hired to explain the equipment to students.','The laboratory demonstrator showed students how to use the equipment; a protest demonstrator would march at a public demonstration.','此句把实验指导员和参加抗议的示威者混为一谈；后半解释表明应使用实验演示义。','confusable')],quiz:[Q('demonstrator',1,1,'A demonstrator outside parliament is most likely?',['taking part in a public protest','teaching a laboratory procedure','repairing a computer privately'],'taking part in a public protest','One sense is someone participating in a demonstration or march.'),Q('demonstrator',2,2,'A university chemistry demonstrator is expected to?',['show students how to perform practical work','lead a political march every morning','write the final exam for every subject'],'show students how to perform practical work','This sense is a person who demonstrates a technique or assists a practical class.'),Q('demonstrator',3,1,'Which report uses demonstrator in the protest sense?',['Demonstrators gathered peacefully to oppose the new law.','The demonstrator connected the laboratory sensor.','The demonstrator calibrated the microscope for a class.'],'Demonstrators gathered peacefully to oppose the new law.','A peaceful public gathering against a law is a protest.'),Q('demonstrator',4,2,'A store demonstrator helps shoppers by?',['showing how a product works','recording them for a court hearing','deciding who may vote'],'showing how a product works','A demonstrator can be a person who presents or explains a product.') ]});
D('demoralise',{etymology:E('Demoralise combines de- with morale and the verb-forming -ise; morale entered English through French from moral. The modern common meaning is to weaken confidence or spirit.','demoralise'),contexts:[C('demoralise.s1','团队士气','A series of cancelled matches began to demoralise the young players, so their coach set smaller goals and praised steady improvement.','一连串比赛取消开始让年轻队员士气低落，于是教练设定较小目标并表扬持续进步。','A series of cancelled matches began to demoralise the young players / so their coach set smaller goals / and praised steady improvement.','demoralise 作及物动词，后接受到打击的人或群体。','连续受挫削弱信心，教练采取措施重振士气，对应 s1。')],mistakes:[M('The clear victory demoralised the team, filling every player with confidence and renewed hope.','The clear victory encouraged the team, filling every player with confidence and renewed hope.','充满信心和希望是鼓舞士气，不是 demoralise（使士气低落）。')],quiz:[Q('demoralise',1,1,'Repeated unexplained delays can demoralise workers by?',['making them lose confidence and motivation','giving them a guaranteed promotion','teaching them a new language'],'making them lose confidence and motivation','Demoralise means to weaken morale, confidence, or hope.'),Q('demoralise',2,1,'Which event is most likely to demoralise a team?',['A last-minute cancellation after months of preparation.','A well-earned win and public praise.','A fair break after a difficult shift.'],'A last-minute cancellation after months of preparation.','Repeated disappointment can lower a group’s morale.'),Q('demoralise',3,1,'Choose the grammatical pattern for this verb.',['The setback demoralised the volunteers.','The setback demoralised of the volunteers.','The volunteers demoralised to the setback.'],'The setback demoralised the volunteers.','Demoralise is transitive here and takes the people whose morale is weakened as its object.'),Q('demoralise',4,1,'If criticism demoralises a learner, the learner is likely to feel?',['discouraged and less confident','more certain of success','physically taller'],'discouraged and less confident','The word describes damage to confidence or spirit.') ]});
D('demulcent',{etymology:E('Demulcent comes from Latin demulcere “to soothe,” formed from de- and mulcere “stroke, caress.” In medicine it describes a substance that soothes an irritated mucous membrane.','demulcent'),contexts:[C('demulcent.s1','药理说明','The pharmacist explained that the syrup has a demulcent effect on an irritated throat, coating the surface and easing discomfort temporarily.','药剂师解释说，这种糖浆对受刺激的咽喉有缓和作用，会覆盖表面并暂时减轻不适。','The pharmacist explained / that the syrup has a demulcent effect on an irritated throat / coating the surface / and easing discomfort temporarily.','demulcent 作形容词，描述对黏膜刺激有缓和作用。','覆盖咽喉表面、减轻不适对应药理义 s1；并非治疗病因。'),C('demulcent.s2','药剂类别','The label classifies the preparation as a demulcent, a soothing agent intended for irritated mucous membranes.','标签将这种制剂归为缓和剂，即用于受刺激黏膜的舒缓药物。','The label classifies the preparation as a demulcent / a soothing agent intended for irritated mucous membranes.','此处 demulcent 作名词，表示一类缓和药剂。','同位语 a soothing agent 解释其药剂名词义 s2。')],mistakes:[M('The demulcent sharply irritated the throat lining and increased the burning sensation.','The demulcent soothed the irritated throat lining and eased the burning sensation.','造成加重刺激的物质与 demulcent 的缓和黏膜作用相反。')],quiz:[Q('demulcent',1,1,'A demulcent medicine is intended to?',['soothe an irritated mucous membrane','increase friction on a sore surface','remove a tooth surgically'],'soothe an irritated mucous membrane','The adjective describes a soothing effect on an irritated internal surface.'),Q('demulcent',2,2,'A bottle labelled “demulcent” contains a?',['soothing agent for an irritated membrane','strong abrasive for polishing metal','substance designed to cause inflammation'],'soothing agent for an irritated membrane','As a noun, demulcent names the soothing medicine or substance.'),Q('demulcent',3,1,'Which sentence uses demulcent as an adjective?',['The honey had a demulcent effect on her sore throat.','The demulcent sat unopened beside the cup.','The throat was a demulcent of the medicine.'],'The honey had a demulcent effect on her sore throat.','Here demulcent modifies effect and describes soothing action.'),Q('demulcent',4,2,'Which item could be described as a demulcent?',['A preparation used to soothe an irritated throat lining.','A solvent used to strip paint from a wall.','A tool used to cut wood.'],'A preparation used to soothe an irritated throat lining.','A demulcent is a soothing agent, especially for mucous membranes.') ]});
D('demur',{etymology:E('Demur came through Anglo-French and Old French demorer “remain, delay,” from Latin demorari. It developed the sense of hesitating or raising an objection, and also names the objection itself.','demur'),contexts:[C('demur.s1','合同讨论','When the landlord proposed an additional fee, the tenants demurred and asked to see the clause that supposedly authorized it.','房东提出额外收费时，租户表示异议，并要求查看据称授权收费的条款。','When the landlord proposed an additional fee / the tenants demurred / and asked to see the clause / that supposedly authorized it.','demur 作不及物动词，表示温和提出异议或犹豫接受。','租户先提出异议再索要依据，体现正式的反对义 s1。'),C('demur.s2','毫无异议','The committee accepted the auditor’s correction without demur once the original figures had been checked.','核对原始数字后，委员会毫无异议地接受了审计员的更正。','The committee accepted the auditor’s correction without demur / once the original figures had been checked.','without demur 是固定表达，意为毫无异议地。','短语直接表现名词义“异议” s2。')],mistakes:[M('She demurred the extra charge and signed the contract without raising any objection.','She demurred at the extra charge and signed the contract only after it was explained.','demur 通常是不及物动词；可说 demur at something，不能直接以 charge 作宾语。','grammar')],quiz:[Q('demur',1,1,'If a tenant demurs at a new fee, the tenant?',['raises a mild objection or hesitates to accept it','pays it immediately without asking','sets fire to the building'],'raises a mild objection or hesitates to accept it','The verb means to object or hesitate, often with at.'),Q('demur',2,2,'“She agreed without demur” means she agreed?',['without making an objection','after starting a loud argument','only after being elected'],'without making an objection','Demur is also a noun meaning an objection.'),Q('demur',3,1,'Which sentence uses the verb naturally?',['He demurred at the proposed change.','He demurred the proposed change directly.','He demurred to the proposed change at it.'],'He demurred at the proposed change.','The verb is intransitive and commonly takes at before the matter objected to.'),Q('demur',4,2,'In “accepted without demur,” demur is?',['a noun meaning objection','an adjective meaning quiet','a verb meaning to deliver'],'a noun meaning objection','The fixed phrase without demur uses the noun sense.') ]});
D('denial',{etymology:E('Denial is formed from deny plus -al; deny came through Old French denier from Latin denegare, “refuse, reject.” Denial can be a statement that something is untrue or a refusal to grant it.','denial'),contexts:[C('denial.s1','事实调查','The agency issued a denial of the bribery allegation, but investigators continued checking the payment records.','该机构否认了贿赂指控，但调查人员仍继续核查付款记录。','The agency issued a denial of the bribery allegation / but investigators continued checking the payment records.','a denial of a claim/allegation 是对其真实性的否认。','机构表示指控不实，属于否认义 s1；否认本身不等于事实已查明。'),C('denial.s2','申请结果','The family received a denial of housing assistance because the application was missing a required income document.','由于申请缺少一份必需的收入文件，这家人收到了住房援助被拒的通知。','The family received a denial of housing assistance / because the application was missing a required income document.','denial of assistance/entry 指拒绝给予援助或准入。','援助申请未获批准，对应拒绝给予义 s2。')],mistakes:[M('The denial of the permit meant the office approved the request and granted permission to build.','The approval of the permit meant the office granted permission to build.','permit 获批是 approval；denial 表示拒绝，二者意思相反。','confusable')],quiz:[Q('denial',1,1,'A denial of an accusation is?',['a statement that the accusation is not true','proof that the accusation has been accepted','a request to repeat the accusation'],'a statement that the accusation is not true','This sense is rejecting a claim as false.'),Q('denial',2,2,'A denial of a visa means the applicant?',['was refused permission','was automatically granted entry','has become a visa officer'],'was refused permission','Denial can name the refusal to grant something.'),Q('denial',3,1,'Which sentence uses denial in the claim sense?',['The company issued a denial of the fraud allegation.','The committee approved a denial of building access.','The denial delivered the package to the office.'],'The company issued a denial of the fraud allegation.','A denial can be an official statement rejecting an allegation.'),Q('denial',4,2,'A letter says “denial of benefits.” What decision does it report?',['The benefits were refused.','The benefits were doubled.','The benefits were sent to another address.'],'The benefits were refused.','Denial of a benefit means refusal to provide it.') ]});
D('denominator',{etymology:E('Denominator is formed from denominate “name” plus the agent/instrument suffix -or, through Medieval Latin denominator. In a fraction it is the number that names the equal parts; figuratively it can be a shared basis.','denominator'),contexts:[C('denominator.s1','分数运算','In the fraction 3/8, the denominator is 8, showing that the whole has been divided into eight equal parts.','在分数 3/8 中，分母是 8，表示整体被分为八个相等部分。','In the fraction 3/8 / the denominator is 8 / showing that the whole has been divided into eight equal parts.','分数中位于横线下方的数是 denominator。','8 位于分数线下，并表明整体分成八份，符合 s1。'),C('denominator.s2','共同基础','Despite their different job titles, the employees shared a common denominator: each had volunteered to mentor new colleagues.','尽管职位名称不同，这些员工有一个共同点：每个人都自愿指导新同事。','Despite their different job titles / the employees shared a common denominator / each had volunteered to mentor new colleagues.','common denominator 比喻共同特征或比较基础。','不同员工都自愿指导新人，这是共性 s2。')],mistakes:[M('In 3/8, the denominator is 3 because it appears above the fraction bar.','In 3/8, the numerator is 3 and the denominator is 8.','分数线下方的 8 才是分母；线上方的 3 是分子。','confusable')],quiz:[Q('denominator',1,1,'What is the denominator of 5/12?',['12','5','17'],'12','The denominator is the number below the fraction line.'),Q('denominator',2,2,'“A shared denominator among the applicants was patience” means they all?',['had patience in common','used the same fraction','applied to become mathematicians'],'had patience in common','Figuratively, a common denominator is a shared quality.'),Q('denominator',3,1,'In the fraction 7/9, which number tells how many equal parts make the whole?',['9','7','16'],'9','The bottom number, 9, is the denominator and names the number of equal parts.'),Q('denominator',4,2,'A researcher compares two groups and seeks a common denominator. The researcher seeks?',['a feature both groups share','the larger fraction bar','a reason to avoid comparison'],'a feature both groups share','The figurative sense is a shared basis or characteristic.') ]});
D('denotation',{etymology:E('Denotation derives from denote, from Latin denotare “mark, indicate,” with the noun-forming -ation. It names a word’s direct reference or the act of indicating by a sign.','denotation'),contexts:[C('denotation.s1','词义分析','In the sentence “The rose was red,” the denotation of rose is the flower, while its associations may include love or beauty.','在“玫瑰是红色的”这句话中，rose 的指称义是这种花，而它的联想意义可能包括爱或美。','In the sentence “The rose was red” / the denotation of rose is the flower / while its associations may include love or beauty.','denotation 与 connotation 对比，指词语直接、字面的所指。','花这一具体所指是 denotation；爱与美属于联想。'),C('denotation.s2','符号指示','On the evacuation map, a red triangle has a specific denotation: the location of the emergency assembly point.','在疏散地图上，红色三角形有明确的指示意义：紧急集合点的位置。','On the evacuation map / a red triangle has a specific denotation / the location of the emergency assembly point.','denotation 也可指符号或标记所表示的对象。','图例符号指向集合点，体现表示/指示义 s2。')],mistakes:[M('The denotation of “home” is its warm, nostalgic feeling rather than any place where someone lives.','The connotation of “home” may be warm or nostalgic; its denotation is a place where someone lives.','温暖怀旧是联想意义；直接所指才是 denotation。','confusable')],quiz:[Q('denotation',1,1,'A word’s denotation is its?',['direct or literal meaning','emotional associations only','pronunciation in a song'],'direct or literal meaning','Denotation is the direct meaning apart from suggested associations.'),Q('denotation',2,2,'A symbol on a map has a denotation when it?',['indicates a particular place or feature','is printed in a large font','has no agreed meaning'],'indicates a particular place or feature','The word can describe what a sign or symbol indicates.'),Q('denotation',3,1,'For the word “snake,” its denotation is the animal; fear and betrayal are its?',['connotations','denominators','demolitions'],'connotations','The direct referent is denotation; associations are connotations.'),Q('denotation',4,2,'A blue sign that marks the nearest exit has a denotation because it?',['points to the exit location','makes the building blue','describes a person’s feelings'],'points to the exit location','A sign’s denotation is the thing or place it indicates.') ]});
D('denouement',{etymology:E('Denouement entered English from French dénouement, literally “an untying,” from dénouer “untie,” based on nouer “tie.” It names the final unravelling or resolution of a plot.','denouement'),contexts:[C('denouement.s1','小说结尾','The novel’s denouement reveals who sent the anonymous letters and explains why the siblings had been kept apart.','小说的结局揭示了匿名信是谁寄出的，并解释了兄妹为何一直分离。','The novel’s denouement reveals who sent the anonymous letters / and explains why the siblings had been kept apart.','denouement 指情节复杂处在结尾得到解释或解决的部分。','匿名信谜团和人物分离原因在结尾被揭晓，符合 s1。')],mistakes:[M('The novel’s denouement introduced the mystery before any conflict or clue appeared.','The novel’s opening introduced the mystery before any conflict or clue appeared.','故事开端提出谜团；denouement 是结尾的揭示和收束。')],quiz:[Q('denouement',1,1,'The denouement of a mystery novel usually?',['reveals how the main complications are resolved','introduces the main characters before the plot starts','lists the author’s bibliography'],'reveals how the main complications are resolved','The denouement is the final unravelling or resolution of a plot.'),Q('denouement',2,1,'Which event belongs in a story’s denouement?',['The detective explains the clues after the culprit is caught.','The first chapter introduces the town.','The author writes a dedication before the story.'],'The detective explains the clues after the culprit is caught.','A denouement settles complications near the end of a plot.'),Q('denouement',3,1,'A reviewer praises the play’s denouement for tying up loose ends. The ending?',['explains unresolved plot points','adds a new cast list','removes the opening scene'],'explains unresolved plot points','The word refers to how the plot’s remaining questions are settled.'),Q('denouement',4,1,'The French literal image behind denouement is an?',['untying of knots','opening of a window','counting of votes'],'untying of knots','The word came from French dénouement, literally “an untying,” a metaphor for resolving plot complications.') ]});
D('densely',{etymology:E('Densely is the adverb formed from dense plus -ly. Dense came through French from Latin densus “thick, crowded”; densely describes close concentration.','densely'),contexts:[C('densely.s1','城市规划','The old quarter is densely populated, with apartment blocks, shops, and schools packed into a small area.','老城区人口稠密，公寓楼、商店和学校集中在一小片区域内。','The old quarter is densely populated / with apartment blocks, shops, and schools / packed into a small area.','densely 修饰 populated，说明人口聚集程度高。','大量居民与设施集中在小区域，体现密集义 s1。')],mistakes:[M('The houses stood densely apart, with kilometres of empty land between every pair.','The houses stood sparsely apart, with kilometres of empty land between every pair.','彼此相隔很远表示稀疏，不是 densely（密集地）。','confusable')],quiz:[Q('densely',1,1,'A densely populated island has?',['many people living in a small area','very few people spread over a huge area','no permanent residents'],'many people living in a small area','Densely describes things crowded close together.'),Q('densely',2,1,'Which scene is described as densely packed?',['Books fill every shelf with almost no gaps.','A single chair stands in an empty hall.','Cars are parked kilometres apart.'],'Books fill every shelf with almost no gaps.','Close spacing and few gaps illustrate dense arrangement.'),Q('densely',3,1,'The forest was densely wooded. What does that imply?',['Trees grew close together.','Only one tree stood in the forest.','The ground was covered with snow only.'],'Trees grew close together.','Densely wooded means containing many trees close together.'),Q('densely',4,1,'Choose the natural use of densely.',['The district is densely populated near the station.','The district is densely a map.','She densely purchased one ticket.'],'The district is densely populated near the station.','The adverb modifies an adjective or participle describing close concentration.') ]});
D('density',{etymology:E('Density comes from French densité and Latin densitas, from densus “thick, crowded.” It names mass per unit volume or, more broadly, how closely people or things occupy an area.','density'),contexts:[C('density.s1','物理实验','The metal’s density was calculated by dividing its measured mass by its volume, allowing the students to compare it with aluminium.','学生用测得的质量除以体积，算出这种金属的密度，并将其与铝进行比较。','The metal’s density was calculated / by dividing its measured mass by its volume / allowing the students to compare it with aluminium.','density 的物理定义是单位体积的质量。','质量除以体积正是计算密度的方法，对应 s1。'),C('density.s2','人口统计','The report maps population density by neighbourhood, revealing crowded districts around the railway and sparsely settled areas near the hills.','报告按社区绘制人口密度地图，显示铁路附近地区拥挤，而山边地区居住稀疏。','The report maps population density by neighbourhood / revealing crowded districts around the railway / and sparsely settled areas near the hills.','population density 衡量单位面积内的人口数量。','对比拥挤和稀疏地区体现人口分布密度义 s2。')],mistakes:[M('To calculate a material’s density, the class multiplied its mass by its volume and called the result mass per unit volume.','To calculate a material’s density, the class divided its mass by its volume to find mass per unit volume.','密度等于质量除以体积，而不是两者相乘。','grammar')],quiz:[Q('density',1,1,'A substance’s density is its?',['mass per unit volume','volume per unit temperature','colour per kilogram'],'mass per unit volume','This is the standard physical meaning of density.'),Q('density',2,2,'A city map shows population density. What does it compare?',['the number of people with the area they occupy','the weight of each resident','the height of every building'],'the number of people with the area they occupy','Population density measures how many people live in a given area.'),Q('density',3,1,'Two blocks have the same volume. The heavier block has greater?',['density','distance','latitude'],'density','With equal volume, greater mass means greater mass per unit volume.'),Q('density',4,2,'A densely settled district has high population density because?',['many residents live in a relatively small area','residents each weigh more','the district contains fewer streets'],'many residents live in a relatively small area','Population density concerns people per unit area, not individual body weight.') ]});
D('dentistry',{etymology:E('Dentistry is formed from dentist plus -ry; dentist derives from French dentiste and dent “tooth,” ultimately from Latin dens, dentis. It names the profession and practice concerned with teeth and oral health.','dentistry'),contexts:[C('dentistry.s1','口腔医疗','After the examination, the student chose dentistry because she wanted to combine clinical care with preventive education about oral health.','检查结束后，这名学生选择了牙科学，因为她希望把临床护理与口腔健康预防教育结合起来。','After the examination / the student chose dentistry / because she wanted to combine clinical care / with preventive education about oral health.','choose/study dentistry 表示选择或学习牙科专业。','临床牙齿护理与口腔预防教育都属于牙科学领域。')],mistakes:[M('Dentistry treats the teeth, but it does not include examining or caring for the gums.','Dentistry treats the teeth and also includes examining and caring for the gums.','牙科实践也包括牙龈和口腔相关问题的检查护理；错误句把牙科范围缩窄了。')],quiz:[Q('dentistry',1,1,'Dentistry is the professional field concerned with?',['teeth and oral health','weather forecasting','the study of ancient coins'],'teeth and oral health','Dentistry covers the practice and medical care of teeth and the mouth.'),Q('dentistry',2,1,'A person who trains in dentistry is preparing to?',['care for patients’ teeth and mouths','design railway timetables','study ocean tides only'],'care for patients’ teeth and mouths','The profession focuses on oral health.'),Q('dentistry',3,1,'Which appointment is most directly part of dentistry?',['A check-up for tooth decay.','A hearing test for musicians.','A survey of river depth.'],'A check-up for tooth decay.','Dental examinations and treatment belong to dentistry.'),Q('dentistry',4,1,'The ending -istry in dentistry contributes to a word naming?',['a profession or field of practice','a single past action','a place where trains stop'],'a profession or field of practice','Dentistry names the professional practice concerned with teeth.') ]});
D('deodorizer',{etymology:E('Deodorizer is formed from deodorize plus -er; deodorize combines de- with odor and means remove or mask an unpleasant smell.','deodorizer'),contexts:[C('deodorizer.s1','家居用品','She placed a deodorizer inside the refrigerator after cleaning the shelves, and the lingering fish smell gradually faded.','清理冰箱搁板后，她在里面放了一种除臭剂，残留的鱼腥味逐渐消散。','She placed a deodorizer inside the refrigerator after cleaning the shelves / and the lingering fish smell gradually faded.','deodorizer 指用于消除或掩盖异味的物质或装置。','冰箱产品减轻异味，符合除臭剂义。')],mistakes:[M('The deodorizer spread a stronger unpleasant smell instead of removing or masking odours.','The deodorizer removed or masked the unpleasant smell.','制造更强异味与 deodorizer 的用途相反。')],quiz:[Q('deodorizer',1,1,'A deodorizer is used to?',['remove or mask an unpleasant smell','make food colder','measure a container'],'remove or mask an unpleasant smell','It is a substance or device that deals with bad odours.'),Q('deodorizer',2,1,'Which is a deodorizer?',['A gel that absorbs smells in a shoe cupboard.','A thermometer for soup.','A brush for shoes.'],'A gel that absorbs smells in a shoe cupboard.','The gel is intended to absorb unpleasant smells.'),Q('deodorizer',3,1,'A car owner installs a deodorizer after a spill to?',['reduce the lingering smell','increase engine speed','test brake fluid'],'reduce the lingering smell','The device addresses an unwanted odour.'),Q('deodorizer',4,1,'The suffix -er in deodorizer most naturally identifies?',['a thing that performs an action','a past-tense verb','a comparison'],'a thing that performs an action','Here -er forms the noun for an agent or device.') ]});
D('departmental',{etymology:E('Departmental is department plus -al. Department came through French département from départir, “divide or separate”; the adjective relates to one division of an organization.','departmental'),contexts:[C('departmental.s1','机构分工','The departmental budget covers laboratory supplies but not salaries managed by the university’s central office.','部门预算涵盖实验室用品，但不包括大学中央办公室管理的工资。','The departmental budget covers laboratory supplies / but not salaries managed by the central office.','departmental 修饰 budget，指某个部门自己的预算。','部门经费与校级经费区分开来。')],mistakes:[M('The departmental report covered the entire national economy and every ministry equally, rather than one organizational division.','The national report covered the entire economy; a departmental report concerns one organizational division.','departmental 指某一部门，不是整个国家或所有部门。')],quiz:[Q('departmental',1,1,'Departmental spending is spending?',['managed by a particular department','paid by every citizen personally','unrelated to any organization'],'managed by a particular department','The adjective relates to an organizational department.'),Q('departmental',2,1,'Which is a departmental matter at a university?',['The biology department’s equipment budget.','The weather over the whole country.','A family grocery list.'],'The biology department’s equipment budget.','The budget belongs to one organizational division.'),Q('departmental',3,1,'A departmental meeting is most likely attended by?',['members of one division','all residents of the country','people unrelated to the organization'],'members of one division','The adjective links the meeting to a department.'),Q('departmental',4,1,'Choose the natural phrase.',['departmental policy','departmental rainfall','departmental yesterday'],'departmental policy','A policy can be specific to one department.') ]});
D('dependably',{etymology:E('Dependably is dependable plus -ly. Dependable is depend plus -able; depend came through French from Latin dependere “hang from, rely on.”','dependably'),contexts:[C('dependably.s1','设备性能','The old pump dependably supplied water throughout the dry season, even when the smaller backup unit failed.','这台旧水泵在整个旱季都稳定供水，即使较小的备用设备失灵也如此。','The old pump dependably supplied water throughout the dry season / even when the backup unit failed.','dependably 修饰 supplied，表示供水稳定、可依靠。','设备持续可靠地工作，体现副词义。')],mistakes:[M('The alarm dependably failed at random every night, so residents could never count on it.','The alarm unreliably failed at random every night, so residents could never count on it.','每晚随机失灵，就不能说设备 dependably 运作。','confusable')],quiz:[Q('dependably',1,1,'A service that operates dependably?',['works reliably so users can count on it','changes its schedule without warning','never accepts customers'],'works reliably so users can count on it','Dependably means reliably, in a trustworthy way.'),Q('dependably',2,1,'Which sentence uses dependably correctly?',['The generator dependably started during each power cut.','The generator dependably failed every time.','The generator dependably is a triangle.'],'The generator dependably started during each power cut.','Repeated successful starts show reliable performance.'),Q('dependably',3,1,'A colleague answers urgent messages dependably. You expect them to?',['respond reliably when needed','ignore every request','change each message’s meaning'],'respond reliably when needed','The adverb describes trustworthy consistency.'),Q('dependably',4,1,'Which is closest in meaning to dependably?',['reliably','accidentally','rarely'],'reliably','Dependably describes consistent, trustworthy action.') ]});
D('dependence',{etymology:E('Dependence is depend plus -ence. Depend came through French from Latin dependere, “hang from”; the noun describes reliance on a person, thing, or substance.','dependence'),contexts:[C('dependence.s1','能源供应','The island’s dependence on imported fuel left household bills vulnerable to shipping delays and sudden price rises.','该岛对进口燃料的依赖使家庭账单容易受到运输延误和价格突涨的影响。','The island’s dependence on imported fuel / left household bills vulnerable / to shipping delays and price rises.','dependence on + 名词表示依靠某物或某人。','岛屿供应依赖进口燃料，体现 reliance 义。')],mistakes:[M('The town’s dependence on the reservoir meant it never relied on that reservoir for water.','The town’s independence from the reservoir meant it never relied on that reservoir for water.','dependence 本身表示依赖；句意“从不依靠”应表达 independence。','confusable')],quiz:[Q('dependence',1,1,'A country’s dependence on one supplier creates risk because it?',['relies heavily on that supplier','has no connection with it','produces all goods itself'],'relies heavily on that supplier','Dependence means the condition of relying on something.'),Q('dependence',2,1,'Which phrase correctly uses the noun?',['dependence on imported gas','dependence at imported gas','dependence by imported gas'],'dependence on imported gas','The usual construction is dependence on something.'),Q('dependence',3,1,'A patient’s dependence on a medicine means the patient?',['relies on it','manufactures it','has never taken it'],'relies on it','The noun describes reliance on a substance.'),Q('dependence',4,1,'Reducing dependence on cars could involve?',['providing reliable public transport','closing every bus route','making walking impossible'],'providing reliable public transport','Alternatives can reduce reliance on cars.') ]});
D('dependent',{etymology:E('Dependent comes from Latin dependens, present participle of dependere “hang from, rely on,” with -ent. It can name a person supported by another or describe something reliant on a factor.','dependent'),contexts:[C('dependent.s1','家庭福利','The benefits form asks each employee to list every dependent who receives financial support from that employee.','福利表要求每位员工列出所有由其提供经济支持的受赡养人。','The benefits form asks each employee to list every dependent / who receives financial support from that employee.','dependent 作名词，指经济上依靠他人的人。','表格登记受雇员赡养的人。'),C('dependent.s2','实验条件','The final result is dependent on the room temperature, so the team recorded it before each measurement.','最终结果取决于室温，因此团队在每次测量前都记录室温。','The final result is dependent on the room temperature / so the team recorded it before each measurement.','be dependent on 表示依赖某条件或取决于某因素。','结果受温度条件影响。')],mistakes:[M('Because the result was dependent on temperature, changing temperature could not affect it.','Because the result was independent of temperature, changing it could not affect the result.','若结果 dependent on 温度，就会受温度影响；不会影响应使用 independent。','confusable')],quiz:[Q('dependent',1,1,'A form asks for a worker’s dependents. These are people who?',['rely on the worker for financial support','supervise the worker’s unit','pay the worker’s salary'],'rely on the worker for financial support','A dependent can be someone financially supported by another.'),Q('dependent',2,2,'If success is dependent on timing, success?',['relies on careful timing','is unrelated to timing','has already happened'],'relies on careful timing','Be dependent on means to rely on or be determined by something.'),Q('dependent',3,1,'Who could be listed as a dependent?',['A child whose living costs are paid by the employee.','The employee’s supervisor.','A stranger who pays the employee’s rent.'],'A child whose living costs are paid by the employee.','The noun refers to someone financially supported by another.'),Q('dependent',4,2,'Choose the natural phrase.',['The schedule is dependent on the weather.','The schedule is dependent of the weather.','The schedule dependent to weather.'],'The schedule is dependent on the weather.','The adjective commonly takes the preposition on.') ]});
D('depiction',{etymology:E('Depiction is depict plus -ion. Depict came from Latin depingere, “paint, portray,” from de- and pingere “paint”; the noun can mean an artistic representation or narrative portrayal.','depiction'),contexts:[C('depiction.s1','艺术作品','The mural’s depiction of the harbour includes fishing boats, repair sheds, and workers unloading crates before dawn.','这幅壁画描绘了港口，其中有渔船、维修棚和黎明前卸货的工人。','The mural’s depiction of the harbour includes fishing boats / repair sheds / and workers unloading crates before dawn.','depiction of + 对象指对其进行的图像或文字再现。','壁画把港口场景呈现在画面中。'),C('depiction.s2','小说叙事','The novel’s depiction of the migrant family follows their changing relationships over three generations rather than focusing on one event.','这部小说对移民家庭的叙述追踪了三代人关系的变化，而非聚焦于某一事件。','The novel’s depiction of the migrant family follows their changing relationships over three generations / rather than one event.','depiction 可指故事呈现人物和事件的方式。','小说通过叙事呈现人物关系。')],mistakes:[M('The mural’s depiction of the harbour contained no image, description, or representation of the harbour at all.','The mural’s omission of the harbour contained no image, description, or representation of the harbour at all.','完全没有描画、描述或再现某对象，就不能称为对它的 depiction。')],quiz:[Q('depiction',1,1,'A depiction of a harbour in a painting is?',['a visual representation of the harbour','the harbour’s location only','the price of the paint'],'a visual representation of the harbour','Depiction means a representation in art or words.'),Q('depiction',2,2,'A critic discusses a novel’s depiction of childhood. The critic studies?',['how the story presents childhood','the paper used to print it only','the author’s travel route'],'how the story presents childhood','This sense concerns how narrative portrays people or events.'),Q('depiction',3,1,'Which is a depiction of a storm?',['A sketch showing dark clouds and waves.','A weather station’s power bill.','A list of book titles.'],'A sketch showing dark clouds and waves.','The sketch represents the storm visually.'),Q('depiction',4,2,'A sympathetic depiction of a villain means the story?',['presents the villain in an understanding way','removes every character','reports the weather outside'],'presents the villain in an understanding way','Narrative depiction describes how a character is presented.') ]});
D('depleted',{etymology:E('Depleted is the past participle and adjective of deplete, from Latin deplere “empty out,” formed from de- and plere “fill.” It describes a supply or resource greatly reduced.','depleted'),contexts:[C('depleted.s1','水库管理','By the end of the drought, the reservoir was so depleted that the city imposed strict limits on garden watering.','干旱结束时，水库水量已经大幅减少，市政府因此严格限制花园浇水。','By the end of the drought / the reservoir was so depleted / that the city limited garden watering.','depleted 描述储量已被消耗、所剩不多。','干旱导致水库水量下降，随后实施限水。')],mistakes:[M('After months without rain, the reservoir was depleted and completely full to the brim.','After months without rain, the reservoir was depleted and nearly empty.','储量 depleted 与水库装满至边缘不相符。')],quiz:[Q('depleted',1,1,'A depleted fuel supply is?',['greatly reduced','newly doubled','unrelated to fuel'],'greatly reduced','Depleted means much of a supply has been used up.'),Q('depleted',2,1,'Which resource could be depleted after heavy use?',['The nutrients in soil.','An untouched warehouse’s full stock.','A river that just flooded.'],'The nutrients in soil.','Heavy use or extraction can reduce available nutrients.'),Q('depleted',3,1,'A team was depleted after an overnight rescue. It was?',['exhausted and low in energy','newly recruited','larger than before'],'exhausted and low in energy','The word can describe drained strength.'),Q('depleted',4,1,'Which sentence uses depleted accurately?',['The depleted battery could no longer power the radio.','The depleted tank overflowed because it was full.','The depleted list added new names.'],'The depleted battery could no longer power the radio.','A depleted battery has lost much of its stored charge.') ]});
D('depletion',{etymology:E('Depletion is deplete plus -ion. Deplete comes from Latin deplere “empty out,” from de- and plere “fill”; depletion is the process or result of using up a supply.','depletion'),contexts:[C('depletion.s1','自然资源','The depletion of the fish population accelerated after several large vessels began trawling near the breeding grounds.','几艘大型渔船开始在繁殖地附近拖网后，鱼类数量的减少加快了。','The depletion of the fish population accelerated / after several vessels began trawling near the breeding grounds.','depletion of + 资源或存量表示其被消耗、减少。','拖网使鱼类种群继续下降。'),C('depletion.s2','体力变化','The athlete’s gradual depletion of energy became obvious in the final kilometre, when her pace dropped sharply.','运动员的体力逐渐耗尽在最后一公里变得明显，她的速度大幅下降。','The athlete’s gradual depletion of energy became obvious / when her pace dropped sharply in the final kilometre.','depletion 也可指体力或储备逐渐流失。','速度下降显示能量正在消耗。')],mistakes:[M('Heavy withdrawals increased depletion of the lake’s water supply, leaving the reservoir fuller than before.','Heavy withdrawals increased the lake’s water supply, leaving the reservoir fuller than before.','depletion 是减少；句中储量变得更满，无法作为耗减的结果。','confusable')],quiz:[Q('depletion',1,1,'The depletion of a forest means?',['a reduction in its trees or resources','planting many new trees','measuring its height only'],'a reduction in its trees or resources','Depletion is using up or reducing a stock.'),Q('depletion',2,2,'The depletion of an athlete’s energy is?',['a gradual loss of strength','an increase in stamina','a change in shoes'],'a gradual loss of strength','The word can describe the draining of energy.'),Q('depletion',3,1,'Which suggests groundwater depletion?',['Wells must go deeper as the water table falls.','The water table rises after heavy rain.','Every well produces more water.'],'Wells must go deeper as the water table falls.','A falling water table indicates shrinking groundwater supply.'),Q('depletion',4,2,'What can help prevent depletion of a limited resource?',['Using it at a rate that allows replenishment.','Taking the entire stock immediately.','Ignoring how much remains.'],'Using it at a rate that allows replenishment.','Careful use slows loss of a resource or reserve.') ]});
D('deplorable',{etymology:E('Deplorable is deplore plus -able. Deplore came from Latin deplorare “bewail, lament”; deplorable describes something so bad that it merits strong disapproval or regret.','deplorable'),contexts:[C('deplorable.s1','公共卫生','Inspectors called the shelter’s deplorable sanitation unacceptable after finding blocked drains, spoiled food, and no clean drinking water.','检查人员发现排水管堵塞、食物变质且没有干净饮用水后，称该收容所卫生状况恶劣得令人无法接受。','Inspectors called the shelter’s deplorable sanitation unacceptable / after finding blocked drains / spoiled food / and no clean water.','deplorable 修饰 sanitation，表示极糟、令人强烈谴责。','多项严重卫生问题支撑负面评价。')],mistakes:[M('Inspectors praised the deplorable conditions as excellent, safe, and fully acceptable.','Inspectors condemned the deplorable conditions as unsafe and unacceptable.','称其 excellent and safe 与 deplorable（恶劣可叹）的评价相反。')],quiz:[Q('deplorable',1,1,'A deplorable safety record is?',['extremely bad and deserving criticism','perfect in every respect','unrelated to safety'],'extremely bad and deserving criticism','Deplorable means very bad and worthy of strong disapproval.'),Q('deplorable',2,1,'Which condition is most plausibly deplorable?',['A school has no safe water or working toilets.','A classroom has new desks and clean windows.','A library has extended its hours.'],'A school has no safe water or working toilets.','Severely inadequate basic conditions deserve strong criticism.'),Q('deplorable',3,1,'A report calls the treatment of workers deplorable. The report?',['strongly condemns it as very bad','praises it as exemplary','says it is too small to measure'],'strongly condemns it as very bad','The adjective conveys a severe negative judgment.'),Q('deplorable',4,1,'Choose a natural collocation.',['deplorable conditions','deplorable delighted','deplorable at noon'],'deplorable conditions','Deplorable commonly modifies conditions or conduct.') ]});
D('deportment',{etymology:E('Deportment is deport “conduct oneself” plus -ment; deport in this sense came through French from Latin deportare. The noun refers to a person’s bearing and manner.','deportment'),contexts:[C('deportment.s1','礼仪考核','The instructor assessed each trainee’s deportment during the formal dinner, noting posture, courtesy, and attention to guests.','导师在正式晚宴上评估每名学员的举止仪态，观察其姿势、礼貌和对宾客的关照。','The instructor assessed each trainee’s deportment during the dinner / noting posture / courtesy / and attention to guests.','deportment 指一个人的举止风度，常用于正式评价。','姿态和待客礼貌都属于受评估的仪态。')],mistakes:[M('The report praised the officer’s deportment, describing rude gestures and disorderly conduct as exemplary.','The report criticized the officer’s deportment, describing rude gestures and disorderly conduct as unacceptable.','粗鲁失序不能支撑“举止典范”的正面评价。')],quiz:[Q('deportment',1,1,'A teacher comments on a student’s deportment. The teacher comments on the student’s?',['bearing and manner','family income','exam timetable'],'bearing and manner','Deportment means a person’s conduct or manner.'),Q('deportment',2,1,'Which observation concerns deportment?',['She stood attentively and greeted visitors courteously.','Her suitcase weighed twelve kilograms.','The room was painted green.'],'She stood attentively and greeted visitors courteously.','Posture and courteous behaviour are aspects of deportment.'),Q('deportment',3,1,'Formal deportment is most relevant at?',['a ceremony where conduct is observed','a private fuel calculation','a geological survey with no participants'],'a ceremony where conduct is observed','The word often concerns judged behaviour in formal settings.'),Q('deportment',4,1,'Which is closest in meaning to deportment?',['bearing','depletion','denotation'],'bearing','Bearing and manner are close meanings of deportment.') ]});
D('deposition',{etymology:E('Deposition comes from Latin depositio, from deponere “put down,” combining de- and ponere “place.” It names material laid down, a sworn legal statement, or removal from high office.','deposition'),contexts:[C('deposition.s1','地质过程','A thick deposition of silt covered the riverbed after floodwaters slowed and dropped the soil they had carried.','洪水减速并沉降所携带的泥土后，河床上覆盖了一层厚厚的淤积物。','A thick deposition of silt covered the riverbed / after floodwaters slowed / and dropped their soil.','deposition 可指沉积过程或沉积下来的物质。','水流减速后泥沙落在河床上。'),C('deposition.s2','法律取证','The lawyer reviewed the witness’s deposition before trial, checking that the sworn account matched dates in the case file.','审判前，律师审阅了证人的宣誓证词，核对陈述是否与案卷日期一致。','The lawyer reviewed the witness’s deposition before trial / checking that the sworn account matched the case dates.','法律语境的 deposition 是正式程序中的宣誓陈述。','witness 与 sworn account 指向法律证词义。')],mistakes:[M('During the deposition, the witness gave an informal unrecorded chat that was neither sworn nor legal testimony.','During the interview, the witness gave an informal unrecorded chat that was neither sworn nor legal testimony.','未宣誓、非正式的闲聊不是法律上的 deposition。','confusable')],quiz:[Q('deposition',1,1,'A river deposition of sand occurs when?',['flowing water drops material it carried','rocks are lifted into the sky','all sediment dissolves'],'flowing water drops material it carried','Deposition is the laying down of transported material.'),Q('deposition',2,2,'A witness gives a deposition before trial. The witness provides?',['a sworn legal statement','a weather forecast','a building permit'],'a sworn legal statement','In law, a deposition is testimony given under oath.'),Q('deposition',3,1,'Which illustrates geological deposition?',['Fine mud settles on a lake bed.','A lawyer questions a witness under oath.','A minister is removed from office.'],'Fine mud settles on a lake bed.','Sediment settling is the material sense.'),Q('deposition',4,2,'Which document would be a deposition?',['A transcript of sworn answers from a witness.','An unsigned shopping list.','A map showing a road.'],'A transcript of sworn answers from a witness.','A deposition records sworn testimony in a legal process.') ]});
D('depositor',{etymology:E('Depositor is deposit plus the agent suffix -or. Deposit comes from Latin depositum “something placed,” from deponere “put down”; a depositor places money or valuables with an institution.','depositor'),contexts:[C('depositor.s1','银行账户','Each depositor received a statement showing the balance and the dates on which funds entered the credit union.','每位存款人都收到一份对账单，列出余额以及资金存入信用合作社的日期。','Each depositor received a statement / showing the balance / and the dates funds entered the credit union.','depositor 指把钱或贵重物品存放在银行等机构的人。','账户余额和入账日期对应存款人义。')],mistakes:[M('The depositor was the bank employee who accepted savings, while the customer who placed the money in the account was not a depositor.','The customer who placed money in the account was the depositor; the bank employee received the deposit.','depositor 是存入资金的客户，不是接收存款的银行员工。','confusable')],quiz:[Q('depositor',1,1,'A depositor at a bank is someone who?',['places money in an account','audits the bank’s roof','prints currency for the government'],'places money in an account','The noun names a person who deposits money or valuables.'),Q('depositor',2,1,'A credit union sends a balance notice to each depositor. They are?',['account holders who placed funds there','employees who repair the building','people who borrowed books'],'account holders who placed funds there','Depositors are those who put funds into the institution.'),Q('depositor',3,1,'Which person is a depositor?',['Mina transfers her savings into a bank account.','A teller prints a blank form.','A courier delivers a letter.'],'Mina transfers her savings into a bank account.','Mina places funds into the account.'),Q('depositor',4,1,'The suffix -or in depositor helps form a noun for?',['a person who performs the action','a place to sleep','the opposite of the action'],'a person who performs the action','A depositor is the person who deposits something.') ]});
D('deprecate',{etymology:E('Deprecate comes from Latin deprecari “pray against, avert by prayer,” from de- and precari “pray.” Modern use means express disapproval or belittle something.','deprecate'),contexts:[C('deprecate.s1','公共政策','The committee deprecated the use of personal data without consent and asked the agency to adopt stricter safeguards.','委员会不赞成未经同意使用个人数据，并要求该机构采取更严格的保护措施。','The committee deprecated the use of personal data without consent / and asked the agency for stricter safeguards.','deprecate 作及物动词，表示公开不赞成某做法。','委员会要求加强保护，体现其反对未经授权使用数据。'),C('deprecate.s2','自我贬低','He deprecated his own contribution as “only a few small edits,” even though he had rewritten the entire report.','尽管他重写了整份报告，他仍把自己的贡献贬低为“只是改了几处小地方”。','He deprecated his own contribution as “only a few small edits” / despite rewriting the entire report.','deprecate 也可表示贬低或轻描淡写某事的价值。','把大量重写说成几处小改动，体现自我贬低义。')],mistakes:[M('The chair deprecated the proposal, meaning she enthusiastically endorsed it and urged everyone to adopt it.','The chair endorsed the proposal, meaning she enthusiastically supported it and urged everyone to adopt it.','deprecate 表示不赞成或贬低，不表示热情支持。','confusable')],quiz:[Q('deprecate',1,1,'A committee may deprecate a practice because it?',['disapproves of or criticizes it','has translated it','has forgotten it exists'],'disapproves of or criticizes it','Deprecate can mean express disapproval.'),Q('deprecate',2,2,'If a speaker deprecates her own achievement, she?',['plays down its importance','claims it belongs to someone else','celebrates it at length'],'plays down its importance','This sense means belittle something.'),Q('deprecate',3,1,'Which sentence means disapprove?',['The report deprecated misleading statistics.','He deprecated his excellent work as “nothing.”','The vendor deprecated old software.'],'The report deprecated misleading statistics.','Here the verb criticizes a practice.'),Q('deprecate',4,2,'Calling a major project “a tiny side task” is to?',['deprecate it','depose it','deplete it'],'deprecate it','The speaker is minimizing the project’s importance.') ]});
D('depreciation',{etymology:E('Depreciation is depreciate plus -ion; depreciate combines de- with price, from Latin pretium “price, value.” It can mean a fall in asset value, accounting write-off, or disparagement.','depreciation'),contexts:[C('depreciation.s1','资产估值','The accountant recorded annual depreciation on the delivery van because its market value declined as it aged.','由于货车随使用年限增加而市场价值下降，会计记录了它的年度折旧。','The accountant recorded annual depreciation on the van / because its market value declined as it aged.','asset depreciation 指资产价值下降及相应会计折旧。','市场价值下降导致记账折旧。'),C('depreciation.s2','他人评价','The essay’s depreciation of rural teachers ignored the difficult conditions in which they worked.','这篇文章对乡村教师的贬低，忽略了他们艰苦的工作条件。','The essay’s depreciation of rural teachers / ignored their difficult working conditions.','depreciation 还可表示贬低、轻视他人。','文章低估教师价值，体现贬低义。')],mistakes:[M('The vehicle gained value every year, so the accountant recorded depreciation to show its rising market price.','The vehicle lost value every year, so the accountant recorded depreciation to show its declining value.','折旧对应资产价值下降，不能记录价值逐年上升。','confusable')],quiz:[Q('depreciation',1,1,'A vehicle’s depreciation usually reflects?',['a decline in value over time','a sudden increase in resale price','the distance between two cities'],'a decline in value over time','Depreciation is the loss or accounting reduction of asset value.'),Q('depreciation',2,2,'An article’s depreciation of a colleague means it?',['belittles the colleague','calculates a car’s value','appoints the colleague to office'],'belittles the colleague','This sense is the act of disparaging someone.'),Q('depreciation',3,1,'Which item is commonly depreciated in accounting?',['A delivery van used by a business.','A river’s direction on a map.','A worker’s lunch break.'],'A delivery van used by a business.','Businesses account for declining value of long-lived assets.'),Q('depreciation',4,2,'“Her depreciation of the volunteers” indicates that she?',['spoke of them as less valuable than they were','recorded their yearly allowance','praised their work generously'],'spoke of them as less valuable than they were','The noun can mean disparagement.') ]});
D('depredate',{etymology:E('Depredate comes from Latin depraedari “plunder,” from de- and praedari “rob, seize as prey.” It means plunder or damage crops and property by attack or feeding.','depredate'),contexts:[C('depredate.s1','农作物损害','Feral pigs depredated the hillside farms at night, rooting up seedlings and damaging irrigation lines.','野猪夜间侵害山坡农场，拱毁幼苗并破坏灌溉管线。','Feral pigs depredated the hillside farms at night / rooting up seedlings and damaging irrigation lines.','depredate 作及物动词，指掠夺或以攻击、取食方式破坏财物。','猪毁坏农作物和设施，体现侵害破坏义。')],mistakes:[M('The grazing cattle depredated the crop by protecting every seedling and leaving the fields untouched.','The grazing cattle depredated the crop by trampling seedlings and eating young plants.','保护幼苗且未触碰田地与 depredate（掠食破坏）矛盾。')],quiz:[Q('depredate',1,1,'Animals that depredate a farm are likely to?',['attack livestock or damage crops','repair its irrigation system','increase its harvest without feeding'],'attack livestock or damage crops','Depredate means plunder or damage by attack or feeding.'),Q('depredate',2,1,'Which sentence uses depredate naturally?',['Rabbits depredated the garden by eating young plants.','Rainfall depredated politely at noon.','The farmer depredated a plan into sections.'],'Rabbits depredated the garden by eating young plants.','Eating and damaging crops illustrates the verb.'),Q('depredate',3,1,'A report says wolves depredated a flock. The wolves?',['attacked or preyed on the sheep','counted them for the farmer','built a fence around the pasture'],'attacked or preyed on the sheep','The verb can describe animals attacking livestock.'),Q('depredate',4,1,'Depredate is closest in meaning to?',['plunder or ravage','soothe','calculate'],'plunder or ravage','Both convey destructive taking or damage.') ]});
D('depredation',{etymology:E('Depredation is depredate plus -ion, from Latin depraedari “plunder.” It names destructive damage or theft caused by attack, often in the plural depredations.','depredation'),contexts:[C('depredation.s1','盗猎破坏','The ranger documented illegal hunters’ depredations, including damaged fences and animals missing from the reserve.','护林员记录了非法猎人的掠夺破坏，包括被毁的围栏和保护区内失踪的动物。','The ranger documented hunters’ depredations / including damaged fences and animals missing from the reserve.','depredations 常用复数，指攻击、掠夺造成的破坏。','猎人造成财产损坏并偷走动物，体现该义。')],mistakes:[M('The report listed the depredations as harmless repairs that left every fence and animal untouched.','The report listed the repairs as harmless work that left every fence and animal untouched.','无害修缮不是 depredation；该词指破坏或掠夺造成的损失。','confusable')],quiz:[Q('depredation',1,1,'The depredations of a pest on crops are?',['damage caused by feeding or attack','a careful planting schedule','an increase in soil minerals'],'damage caused by feeding or attack','Depredation is destructive damage or theft.'),Q('depredation',2,1,'A historian describes wartime depredations. They were?',['destruction and plunder','peaceful rebuilding only','weather changes'],'destruction and plunder','The noun often describes damage caused by attack.'),Q('depredation',3,1,'Which phrase is natural?',['the depredations of locusts','the depredation of a polite greeting','depredation a cup of tea'],'the depredations of locusts','Locusts can cause destructive crop losses.'),Q('depredation',4,1,'A village reports depredation of its orchards. It reports?',['damage caused by attacks or feeding','a harvest celebration','a new pruning method'],'damage caused by attacks or feeding','The noun denotes destructive losses, often from animals or raiders.') ]});
D('depression',{etymology:E('Depression comes from Latin depressio, from deprimere “press down,” combining de- and premere “press.” It can mean low mood, economic contraction, or a low-lying landform.','depression'),contexts:[C('depression.s1','心理健康','After months of persistent low mood and loss of interest, he spoke with a clinician about depression and possible treatment.','持续数月情绪低落、失去兴趣后，他与临床医生讨论了抑郁症及可能的治疗方案。','After months of persistent low mood and loss of interest / he spoke with a clinician about depression.','depression 在心理健康语境可指持续的抑郁状态或疾病。','持续的低落情绪和兴趣减退需要临床讨论。'),C('depression.s2','宏观经济','During the depression, factories cut production, unemployment rose, and families postponed major purchases.','经济萧条期间，工厂削减产量、失业率上升，家庭推迟大宗消费。','During the depression / factories cut production / unemployment rose / and families postponed purchases.','经济语境中 depression 指持续的严重低迷。','产量和就业下滑体现经济义。'),C('depression.s3','地貌描述','Rainwater collected in a shallow depression in the meadow, a low area surrounded by slightly higher ground.','雨水聚集在草地的一处浅洼地里，周围地势略高。','Rainwater collected in a shallow depression in the meadow / surrounded by slightly higher ground.','地理名词 depression 指地表低洼处。','地面低于周围地势，符合地貌义。')],mistakes:[M('The depression in the meadow rose above the surrounding hills and drained water from higher ground.','The ridge in the meadow rose above the surrounding hills and drained water from higher ground.','depression 是低洼处，不能指高出周围的山脊。','confusable')],quiz:[Q('depression',1,1,'Persistent depression in the clinical sense may involve?',['lasting low mood and loss of interest','a brief preference for one colour','a rise in factory output'],'lasting low mood and loss of interest','The mental-health sense concerns persistent sadness or related symptoms.'),Q('depression',2,2,'An economic depression is marked by?',['prolonged low economic activity','rapid growth in every industry','a geological valley only'],'prolonged low economic activity','This sense is an extended period of low economic activity.'),Q('depression',3,3,'On a topographic map, a depression is?',['a low area of land','a high mountain peak','a straight road'],'a low area of land','The geographical sense is land lower than its surroundings.'),Q('depression',4,2,'Which news report uses depression economically?',['Unemployment rose during the prolonged downturn.','A patient sought help for persistent sadness.','A pond filled a hollow in a field.'],'Unemployment rose during the prolonged downturn.','Unemployment and downturn signal the economic meaning.') ]});
D('deprival',{etymology:E('Deprival is deprive plus -al. Deprive came through French from Latin privare “rob, strip”; deprival is a less common noun for the act or state of being deprived.','deprival'),contexts:[C('deprival.s1','权益讨论','The report examined the deprival of residents’ access to the river after a private fence blocked the only public path.','私人围栏挡住唯一公共通道后，报告考察了居民通往河边的权利被剥夺一事。','The report examined the deprival of residents’ access to the river / after a fence blocked the only public path.','deprival of + 权利、条件或物品，表示将其剥夺。','公共通道受阻导致 access 被拿走。')],mistakes:[M('The deprival of residents’ access meant the public path remained open for everyone to use.','The preservation of residents’ access meant the public path remained open for everyone to use.','通道仍完全开放表示权利未被剥夺，与 deprival 冲突。','confusable')],quiz:[Q('deprival',1,1,'The deprival of a legal right is?',['the taking away of that right','the automatic expansion of that right','a record of its spelling'],'the taking away of that right','Deprival names a loss caused by taking something away.'),Q('deprival',2,1,'Which phrase uses deprival naturally?',['the deprival of access to clean water','the deprival of a cake into slices','deprival the report carefully'],'the deprival of access to clean water','A person can be deprived of access or a necessary resource.'),Q('deprival',3,1,'A study of sensory deprival would investigate?',['the removal or lack of sensory input','an increase in the number of senses','the price of a hearing aid'],'the removal or lack of sensory input','The noun describes being deprived of a condition or resource.'),Q('deprival',4,1,'Which is closest to deprival?',['deprivation','approval','arrival'],'deprivation','Both nouns describe the act or state of being deprived.') ]});
D('deprivation',{etymology:E('Deprivation is deprive plus -ation. Deprive came through French from Latin privare “rob, strip”; deprivation is a lack of necessities or the act of taking something away.','deprivation'),contexts:[C('deprivation.s1','社会条件','Children in the remote settlement faced material deprivation because reliable heating, fresh food, and medical care were difficult to obtain.','偏远定居点的儿童面临物质匮乏，因为可靠供暖、新鲜食物和医疗服务都难以获得。','Children in the remote settlement faced material deprivation / because heating / fresh food / and medical care were difficult to obtain.','material deprivation 指缺少舒适生活所需的基本物品和服务。','供暖、食物和医疗等基本需要不足。'),C('deprivation.s2','制度剥夺','The court considered whether the deprivation of the family’s property had occurred without due process.','法院审查该家庭财产被剥夺是否未经正当程序。','The court considered whether the deprivation of the family’s property / had occurred without due process.','deprivation of + 物品或权利可指将其拿走的行为。','财产被剥夺的法律行为对应此义。')],mistakes:[M('Material deprivation describes a household with secure housing, sufficient food, dependable heating, and easy access to care.','Material security describes a household with secure housing, sufficient food, dependable heating, and easy access to care.','基本生活需要充足的状态不是 material deprivation。','confusable')],quiz:[Q('deprivation',1,1,'Material deprivation most directly means?',['lacking goods or services needed for a decent life','having more luxury goods than needed','a method of calculating income tax'],'lacking goods or services needed for a decent life','This sense is a serious lack of necessities.'),Q('deprivation',2,2,'The deprivation of a licence means?',['the licence was taken away','the licence was renewed','the licence was copied twice'],'the licence was taken away','This sense is the act of taking something from someone.'),Q('deprivation',3,1,'Which group faces deprivation in the basic-needs sense?',['Families without safe housing or reliable food.','Families with every essential service.','Tourists choosing between hotels.'],'Families without safe housing or reliable food.','The word can describe lacking necessities for a decent life.'),Q('deprivation',4,2,'A report alleges deprivation of voting rights. It alleges the rights were?',['taken away','printed incorrectly','given to everyone'],'taken away','Deprivation can mean taking a right from someone.') ]});
D('deprived',{etymology:E('Deprived is the past participle and adjective of deprive, from Latin privare “rob, strip.” It commonly describes people who lack resources or necessities needed for a decent life.','deprived'),contexts:[C('deprived.s1','教育机会','The after-school program offers tutoring and meals to children in deprived neighbourhoods where household incomes and services are limited.','课后项目为贫困社区的儿童提供辅导和餐食，这些地区的家庭收入和公共服务都有限。','The after-school program offers tutoring and meals / to children in deprived neighbourhoods / where incomes and services are limited.','deprived 修饰 neighbourhoods，表示基本资源或机会不足。','收入和服务不足说明社区处于匮乏状态。')],mistakes:[M('The report called the district deprived, although every household had secure housing, abundant food, and comprehensive public services.','The report called the district well-provided-for, because every household had secure housing, abundant food, and comprehensive public services.','基本生活资源和服务充足，不符合 deprived 所表达的匮乏。','confusable')],quiz:[Q('deprived',1,1,'A deprived neighbourhood is one where residents?',['lack important resources or services','have every service in abundance','live far from others by choice only'],'lack important resources or services','Deprived means lacking things considered necessary for a decent life.'),Q('deprived',2,1,'Which support might benefit a deprived community?',['Access to safe housing, healthcare, and schooling.','Removing the only public clinic.','Closing the local school without replacement.'],'Access to safe housing, healthcare, and schooling.','These are resources a deprived community may lack.'),Q('deprived',3,1,'An economically deprived area has?',['limited income and material resources','wealth among every resident','a temporary road closure'],'limited income and material resources','Economically deprived means lacking material resources.'),Q('deprived',4,1,'Choose the accurate sentence.',['The deprived village lacked reliable clean water.','The deprived village had every need easily met.','The deprived village was a past-tense verb.'],'The deprived village lacked reliable clean water.','Lack of a basic service is consistent with being deprived.') ]});
D('derange',{etymology:E('Derange came through French déranger, from Old French desrengier, “put out of order,” from de- and rang “row, rank.” It means disrupt an arrangement or, in older usage, unsettle someone’s mind.','derange'),contexts:[C('derange.s1','机械维护','A loose bearing could derange the alignment of the press, so the technician shut the machine down before the rollers were damaged.','松动的轴承可能扰乱压机的对齐状态，因此技术员在滚筒损坏前关闭了机器。','A loose bearing could derange the alignment of the press / so the technician shut it down before damage.','derange 作及物动词，表示扰乱系统或安排。','轴承失灵可能破坏设备对齐，体现 s1。'),C('derange.s2','旧式文学用法','In the nineteenth-century novel, the sudden inheritance seemed to derange the young heir, who began speaking incoherently.','在这部十九世纪小说中，突如其来的遗产似乎使年轻继承人精神失常，他开始语无伦次。','In the nineteenth-century novel / the sudden inheritance seemed to derange the young heir / who began speaking incoherently.','此义是使人精神失常，属旧式或敏感表达。','小说直接描述其精神状态失常，对应 s2。')],mistakes:[M('The miswired controls deranged the machine’s sequence, making every step run in its proper order.','The miswired controls deranged the machine’s sequence, making the steps run out of order.','derange 是扰乱；句子结果“proper order”与此相反。')],quiz:[Q('derange',1,1,'A fault may derange a machine’s controls by?',['disrupting their normal arrangement','making them work in perfect order','painting them a new colour'],'disrupting their normal arrangement','Derange means to throw a system or plan into disorder.'),Q('derange',2,2,'In an older novel, to derange a character can mean to?',['make the person mentally unbalanced','appoint the person as a designer','repair the person’s coat'],'make the person mentally unbalanced','This is an older sense describing mental disturbance.'),Q('derange',3,1,'Which sentence uses derange in the mechanical sense?',['The impact deranged the gears inside the clock.','She deranged a new poster on the wall.','The clock deranged exactly at noon.'],'The impact deranged the gears inside the clock.','The impact disrupted the arrangement of the gears.'),Q('derange',4,1,'A sudden schedule change deranged the conference plan. The plan was?',['thrown into disorder','made more orderly','translated into another language'],'thrown into disorder','The verb can describe disruption of an arrangement or plan.') ]});
D('derelict',{etymology:E('Derelict came from Latin derelictus, past participle of derelinquere “abandon,” from de- and relinquere “leave behind.” It can describe something abandoned or name an abandoned person or thing.','derelict'),contexts:[C('derelict.s1','城市建筑','The council fenced off the derelict hotel, whose broken windows and leaking roof made it unsafe to enter.','市议会围起了这家废弃的酒店，破碎的窗户和漏水的屋顶使其不能安全进入。','The council fenced off the derelict hotel / whose broken windows and leaking roof made it unsafe.','derelict 作形容词，指被遗弃且破败的。','酒店空置失修并有危险，对应 s1。'),C('derelict.s2','无家可归者','The outreach team offered meals and shelter to derelicts living near the abandoned station.','援助小组向住在废弃车站附近的流浪者提供食物和住所。','The outreach team offered meals and shelter / to derelicts living near the abandoned station.','derelict 作名词可指无家可归或无依无靠的人，语气可能冒犯，应谨慎使用。','提供食宿的对象是无家可归的人，对应 s2。')],mistakes:[M('The derelict warehouse had just been fully restored, was occupied by a thriving business, and showed no sign of neglect.','The restored warehouse was occupied by a thriving business and showed no sign of neglect.','有人使用且全面修复、无失修迹象的建筑不应称作 derelict。')],quiz:[Q('derelict',1,1,'A derelict factory is likely to be?',['abandoned and in poor condition','newly built and fully maintained','busy with workers on every floor'],'abandoned and in poor condition','As an adjective, derelict describes something deserted and neglected.'),Q('derelict',2,2,'In older or formal writing, a derelict may be?',['a person without a home or means','a newly appointed official','a well-maintained building'],'a person without a home or means','The noun sense can refer to an abandoned or homeless person.'),Q('derelict',3,1,'Which clue suggests a building is derelict?',['Its roof has collapsed after years of neglect.','It opened last week with full staffing.','Its rooms are freshly repaired and occupied.'],'Its roof has collapsed after years of neglect.','Long-term neglect and poor condition fit the adjective.'),Q('derelict',4,2,'A shelter provides beds for derelicts. The beds are for people who?',['lack a home or reliable means of support','design buildings professionally','own several apartment blocks'],'lack a home or reliable means of support','This noun sense refers to people left without a home or means.') ]});
D('dereliction',{etymology:E('Dereliction comes from Latin derelictio, from derelinquere “abandon.” It names either shameful neglect of a responsibility or the condition of being abandoned and ruined.','dereliction'),contexts:[C('dereliction.s1','职业责任','The inquiry found dereliction of duty when the supervisor ignored three warnings about the unsafe platform.','调查认定主管忽视了关于平台不安全的三次警告，构成玩忽职守。','The inquiry found dereliction of duty / when the supervisor ignored three warnings about the unsafe platform.','dereliction of duty 是固定搭配，指严重失职。','忽视安全警告属于对职责的严重疏忽。'),C('dereliction.s2','房屋荒废','Years of dereliction left the manor’s roof open to rain and its gardens overgrown with weeds.','多年的荒废使庄园屋顶漏雨，花园也长满杂草。','Years of dereliction left the manor’s roof open to rain / and its gardens overgrown.','dereliction 可指被弃置、失修的状态。','建筑破败、花园荒芜体现 s2。')],mistakes:[M('The inspector praised the supervisor for dereliction of duty because she followed every safety procedure.','The inspector praised the supervisor for fulfilling her duty because she followed every safety procedure.','遵守全部安全程序是履职，不是 dereliction of duty。','confusable')],quiz:[Q('dereliction',1,1,'Dereliction of duty is?',['serious neglect of one’s responsibilities','careful completion of every task','a scheduled day off'],'serious neglect of one’s responsibilities','The phrase means shameful neglect of a duty.'),Q('dereliction',2,2,'Years of dereliction can leave a house?',['abandoned and in ruins','newly painted and occupied','larger than it was before'],'abandoned and in ruins','The other sense is a condition of abandonment and decay.'),Q('dereliction',3,1,'A guard ignores an alarm and leaves a gate open. An inquiry may call this?',['dereliction of duty','a promotion','a building permit'],'dereliction of duty','Ignoring assigned responsibilities is dereliction.'),Q('dereliction',4,2,'The phrase “a landscape of dereliction” suggests?',['neglect and abandonment','careful gardening','new construction'],'neglect and abandonment','The noun can name an abandoned or ruined condition.') ]});
D('derisive',{etymology:E('Derisive is formed from deride plus -ive. Deride came from Latin deridere, “laugh at, mock,” from de- and ridere “laugh”; derisive describes contemptuous mockery or something so poor it invites scorn.','derisive'),contexts:[C('derisive.s1','嘲讽反应','The proposal received a derisive laugh from the audience after its author claimed the bridge could be built in a single afternoon.','作者声称这座桥一个下午就能建成后，提案引来观众嘲讽的笑声。','The proposal received a derisive laugh from the audience / after its author made an implausible claim.','derisive 修饰 laugh，表示带有轻蔑嘲笑。','观众以嘲笑回应荒谬说法，符合 s1。'),C('derisive.s2','引人鄙夷','The contractor’s derisive offer of five dollars for a week of skilled work was rejected immediately.','承包商提出一周熟练工作只付五美元，这种可鄙的报价立刻遭到拒绝。','The contractor’s derisive offer of five dollars for a week of skilled work / was rejected immediately.','derisive 可形容低劣到令人不屑的事物。','报酬低得荒唐，招致轻蔑，对应 s2。')],mistakes:[M('She gave him a derisive smile to show sincere respect and admiration for his answer.','She gave him an admiring smile to show respect for his answer.','表达尊重和赞赏的笑不是轻蔑嘲笑。','confusable')],quiz:[Q('derisive',1,1,'A derisive comment is meant to?',['mock or show contempt','offer sincere praise','give technical instructions'],'mock or show contempt','Derisive means expressing contempt by laughing at someone.'),Q('derisive',2,2,'A derisive wage offer is likely to be?',['so low that it invites scorn','generous and above the market rate','a written record of hours'],'so low that it invites scorn','The adjective can describe something contemptibly inadequate.'),Q('derisive',3,1,'Which reaction is derisive?',['A crowd laughs scornfully at a boast.','A class applauds a careful explanation.','A friend quietly offers help.'],'A crowd laughs scornfully at a boast.','Scornful laughter illustrates the mocking sense.'),Q('derisive',4,2,'Calling a tiny payment for expert work derisive emphasizes that it is?',['contemptibly inadequate','exactly fair','legally required'],'contemptibly inadequate','The offer is so poor that it deserves scorn.') ]});
D('derivation',{etymology:E('Derivation comes from Latin derivatio, from derivare “draw off, derive,” formed from de- and rivus “stream.” It can name the origin or development of a word, or a result obtained by logical steps.','derivation'),contexts:[C('derivation.s1','词源说明','The dictionary gives the derivation of “salary” from a Latin word associated with salt, while noting that the historical details remain debated.','词典指出 salary 源自一个与盐有关的拉丁词，同时说明具体历史细节仍有争议。','The dictionary gives the derivation of “salary” from a Latin word associated with salt / while noting that details remain debated.','derivation of a word 指词的来源及演变过程。','词典讨论该词来源并注明争议，符合 s1。'),C('derivation.s2','数学推导','The derivation of the formula begins with the conservation equation and proceeds through three algebraic steps.','该公式的推导从守恒方程开始，并经过三个代数步骤。','The derivation of the formula begins with the conservation equation / and proceeds through three algebraic steps.','数学中 derivation 是通过逻辑步骤得到公式或结果的过程。','由方程逐步推得公式，对应 s2。')],mistakes:[M('The derivation of the formula skipped every logical step and simply guessed an unrelated answer.','The derivation of the formula showed the logical steps leading to the answer.','无推导过程、随意猜测不能称为 derivation。')],quiz:[Q('derivation',1,1,'A word’s derivation explains?',['where it came from and how it developed','how loudly it is spoken','how many letters it contains only'],'where it came from and how it developed','This sense concerns the origin and development of a word or idea.'),Q('derivation',2,2,'A mathematical derivation shows?',['the steps used to obtain a result','the colour of the equation','the author’s birthplace'],'the steps used to obtain a result','The mathematical sense is a result reached through logical steps.'),Q('derivation',3,1,'A linguist researches the derivation of a borrowed word by tracing?',['its historical source and changes','the word’s font size','the speaker’s pulse'],'its historical source and changes','Derivation can mean origin and development.'),Q('derivation',4,2,'Which is a derivation of a formula?',['A proof that proceeds from assumptions to the formula.','A guess with no reasoning.','A list of unrelated symbols.'],'A proof that proceeds from assumptions to the formula.','A derivation sets out reasoning that produces a formula.') ]});
D('dermatology',{etymology:E('Dermatology combines dermato-, from Greek derma “skin,” with -logy, “study.” The medical specialty deals with the skin and related structures such as hair and nails.','dermatology'),contexts:[C('dermatology.s1','医学专科','After the rash failed to improve, the family doctor referred him to dermatology for an assessment of his skin and scalp.','皮疹一直没有好转后，家庭医生将他转诊至皮肤科，评估他的皮肤和头皮状况。','After the rash failed to improve / the family doctor referred him to dermatology / for an assessment of his skin and scalp.','refer someone to dermatology 表示转诊至皮肤科。','对皮肤和头皮问题进行专科评估，符合医学学科义。')],mistakes:[M('Dermatology treats disorders of hair but never deals with skin.','Dermatology treats disorders of hair and also deals with skin.','Dermatology includes care for skin and related structures such as hair and nails.')],quiz:[Q('dermatology',1,1,'Dermatology is the medical study and treatment of?',['skin and related conditions','the heart’s electrical rhythm','the history of coins'],'skin and related conditions','Dermatology is the medical specialty for skin, hair, and nails.'),Q('dermatology',2,1,'A dermatologist would most likely assess?',['a persistent skin rash','a broken railway signal','a ship’s fuel consumption'],'a persistent skin rash','Skin disorders fall within dermatology.'),Q('dermatology',3,1,'Which clinic belongs to dermatology?',['A clinic treating eczema and acne.','A clinic adjusting hearing aids.','A clinic measuring river flow.'],'A clinic treating eczema and acne.','Eczema and acne affect the skin.'),Q('dermatology',4,1,'The element dermato- in dermatology refers to?',['skin','water','speech'],'skin','The Greek-derived combining form means skin.') ]});
D('derrick',{etymology:E('Derrick was named from the surname of Thomas Derrick, an Elizabethan English hangman; the word came to name a gallows-like lifting frame and then an oil-well tower.','derrick'),contexts:[C('derrick.s1','油田作业','Workers inspected the derrick above the oil well before raising the drill string for the next section of the bore.','工人在提升钻柱以继续钻井前，检查了油井上方的井架。','Workers inspected the derrick above the oil well / before raising the drill string.','derrick 指油井上方的高塔式井架，也可指人字起重机。','油井与钻柱作业清楚指向井架义。')],mistakes:[M('The crew dismantled the derrick, the small underground pipe that carries oil to a house.','The crew repaired the derrick, the tall tower above the oil well that supports drilling equipment.','derrick 是地面井架或起重架，不是地下输油管。','confusable')],quiz:[Q('derrick',1,1,'An oil-field derrick is?',['a tall structure supporting drilling equipment','a tank used to store drinking water','a map of underground rivers'],'a tall structure supporting drilling equipment','A derrick is the tower built over an oil well.'),Q('derrick',2,1,'Workers inspect a derrick before drilling because it?',['supports the drilling operation','filters drinking water','measures a ship’s speed'],'supports the drilling operation','The structure holds or supports drilling equipment.'),Q('derrick',3,1,'Which object could also be called a derrick?',['A hinged-boom lifting frame.','A handheld compass.','A household cooking pot.'],'A hinged-boom lifting frame.','Derrick can also refer to a crane with a hinged boom.'),Q('derrick',4,1,'Choose the natural phrase.',['the derrick above an oil well','a derrick of sea salt','derrick the witness under oath'],'the derrick above an oil well','Oil-well derrick is a standard collocation.') ]});
D('desalination',{etymology:E('Desalination is formed from desalinate plus -ion. Desalinate combines de- “remove” with saline/salt and means remove dissolved salt from water.','desalination'),contexts:[C('desalination.s1','供水工程','The coastal city expanded desalination to turn seawater into drinking water during the long drought.','长期干旱期间，这座沿海城市扩大海水淡化规模，把海水转为饮用水。','The coastal city expanded desalination / to turn seawater into drinking water during the drought.','desalination 指从海水或微咸水中除盐的过程。','海水经过除盐处理后成为可用淡水。')],mistakes:[M('Desalination adds more dissolved salt to seawater so that it becomes safe drinking water.','Desalination removes dissolved salt from seawater so that it can become usable fresh water.','desalination 是去除盐分，不是增加盐分。','confusable')],quiz:[Q('desalination',1,1,'Desalination is the process of?',['removing salt from seawater or brackish water','adding salt to fresh water','freezing water without changing its salt content'],'removing salt from seawater or brackish water','The process removes salt to make water usable.'),Q('desalination',2,1,'A desalination plant helps a dry coastal region by?',['producing fresh water from seawater','turning fresh water into oil','increasing the ocean’s salinity'],'producing fresh water from seawater','Removing dissolved salts yields usable water.'),Q('desalination',3,1,'Which problem could desalination help address?',['A shortage of fresh water near the coast.','A shortage of sunlight in winter.','A lack of road signs.'],'A shortage of fresh water near the coast.','It provides another water source by treating salty water.'),Q('desalination',4,1,'The prefix de- in desalination signals?',['removal or reversal','a person who performs a job','a comparison of two amounts'],'removal or reversal','Desalination removes salt from the water.') ]});
D('descriptive',{etymology:E('Descriptive is describe plus -ive; describe came through French from Latin describere “write down, copy,” formed from de- and scribere “write.” The adjective presents what something is like, without necessarily judging it.','descriptive'),contexts:[C('descriptive.s1','写作方式','The report is descriptive rather than persuasive: it records what residents observed but does not argue for a particular policy.','这份报告以描述为主而非说服：它记录居民观察到的情况，但不主张某项具体政策。','The report is descriptive rather than persuasive / it records residents’ observations / but does not argue for a policy.','descriptive 表示说明事物状况，而不一定作评价或劝说。','报告记录观察而不主张立场，体现描述义。')],mistakes:[M('The report was descriptive because it argued that the government must close the road immediately.','The report was persuasive because it argued that the government must close the road immediately.','An argument urging a specific action is persuasive rather than merely descriptive.')],quiz:[Q('descriptive',1,1,'A descriptive paragraph mainly?',['says what something is like','orders readers to take action','proves a theorem'],'says what something is like','Descriptive writing presents features or details.'),Q('descriptive',2,1,'Which is a descriptive sentence?',['The narrow bridge has three stone arches.','Everyone must repair the bridge tomorrow.','The bridge should be closed by law.'],'The narrow bridge has three stone arches.','It reports observable features without making an argument.'),Q('descriptive',3,1,'A descriptive report about a neighbourhood would include?',['details of its streets, buildings, and services','only a command to move away','a recipe for soup'],'details of its streets, buildings, and services','The adjective concerns saying what a place is like.'),Q('descriptive',4,1,'“The sky turned grey and the wind strengthened” is?',['descriptive','a mathematical derivation','a denial of entry'],'descriptive','The sentence depicts observable conditions.') ]});
D('desegregate',{etymology:E('Desegregate is de- plus segregate. Segregate derives from Latin segregare “separate from the flock”; desegregate means end imposed separation, especially racial segregation, by opening an institution to all groups.','desegregate'),contexts:[C('desegregate.s1','教育平权','The court ordered the district to desegregate its schools and provide students from every community equal access to classrooms.','法院命令该学区取消学校隔离，让所有社区的学生平等进入课堂。','The court ordered the district to desegregate its schools / and provide students from every community equal access.','desegregate 作及物动词，表示废除隔离制度。','命令所有社区学生平等入学，体现取消隔离义。')],mistakes:[M('The district desegregated its schools by assigning children to separate buildings solely according to race.','The district segregated its schools by assigning children to separate buildings solely according to race.','按种族分开安排学校是 segregation，不是 desegregation。','confusable')],quiz:[Q('desegregate',1,1,'To desegregate a school system is to?',['end enforced separation and open schools to all groups','separate pupils by race','close every classroom permanently'],'end enforced separation and open schools to all groups','Desegregate means abolish segregation.'),Q('desegregate',2,1,'Which action would desegregate a public pool?',['Allowing people of all racial groups to use it equally.','Barring one group from entering.','Assigning different hours by race.'],'Allowing people of all racial groups to use it equally.','Equal access ends the imposed separation.'),Q('desegregate',3,1,'The prefix de- in desegregate signals?',['undoing or ending segregation','a person who segregates','a measurement of a group'],'undoing or ending segregation','The verb means reverse segregation.'),Q('desegregate',4,1,'A court ordered a university to desegregate. The university must?',['end racial separation in access or facilities','create separate facilities by race','cancel all admissions'],'end racial separation in access or facilities','Desegregation opens institutions rather than separating groups.') ]});
D('desertification',{etymology:E('Desertification is desertify plus -cation; desertify is desert plus -ify, “make or become.” The noun names fertile land turning desert-like and the spread of dry, barren conditions.','desertification'),contexts:[C('desertification.s1','土地退化','Overgrazing and years of drought accelerated desertification, leaving once-fertile fields with little vegetation.','过度放牧和多年干旱加速了荒漠化，使曾经肥沃的田地几乎没有植被。','Overgrazing and years of drought accelerated desertification / leaving once-fertile fields with little vegetation.','desertification 指肥沃土地逐渐变得荒漠化的过程。','干旱和过度放牧造成土地退化，符合 s1。'),C('desertification.s2','区域扩展','Satellite images show desertification spreading beyond the original dry zone into neighbouring grasslands.','卫星图像显示荒漠化正从原来的干旱区扩展到邻近草原。','Satellite images show desertification spreading beyond the original dry zone / into neighbouring grasslands.','该词也可突出干旱、贫瘠环境向周边扩展。','荒漠状况向草原蔓延，对应 s2。')],mistakes:[M('Desertification restored the region’s fertile topsoil and caused dense vegetation to spread across the fields.','Reforestation restored the region’s fertile topsoil and caused dense vegetation to spread across the fields.','土壤恢复、植被扩张与荒漠化造成的土地干旱贫瘠相反。','confusable')],quiz:[Q('desertification',1,1,'Desertification is the change of?',['productive land into desert-like, barren land','desert into a rainforest overnight','a city into a farming village'],'productive land into desert-like, barren land','The process degrades fertile land into dry, barren conditions.'),Q('desertification',2,2,'Desertification spreading into grassland means?',['dry and barren conditions are expanding','the grassland is becoming wetter everywhere','a desert is shrinking into a lake'],'dry and barren conditions are expanding','This sense emphasizes the spread of desert-like conditions.'),Q('desertification',3,1,'Which factors can contribute to desertification?',['Prolonged drought and overgrazing.','Careful soil conservation and native planting.','Regular replenishment of groundwater.'],'Prolonged drought and overgrazing.','Drought and land misuse can degrade fertile soil.'),Q('desertification',4,1,'Which observation is evidence of desertification?',['Fertile fields lose vegetation and topsoil.','A forest becomes denser after replanting.','A river carries more water after rain.'],'Fertile fields lose vegetation and topsoil.','Loss of vegetation and soil fertility is consistent with land becoming desert-like.') ]});
D('desiccation',{etymology:E('Desiccation is formed from desiccate plus -ion. Desiccate comes from Latin desiccare “dry up,” from de- and siccare “make dry”; the noun is the removal or loss of moisture.','desiccation'),contexts:[C('desiccation.s1','食品保存','Desiccation preserved the thin apple slices by removing their moisture, making them light enough to store for the winter.','脱水干燥通过去除薄苹果片中的水分来保存它们，使其轻到可以储存过冬。','Desiccation preserved the thin apple slices / by removing their moisture / making them light enough to store.','desiccation 指使物体彻底干燥或水分流失的过程。','去除水分以保存食物，体现干燥义。')],mistakes:[M('Desiccation left the wet cloth saturated with water and heavier than before.','Rehydration left the dry cloth saturated with water and heavier than before.','吸水变湿是 rehydration，与去除水分的 desiccation 相反。','confusable')],quiz:[Q('desiccation',1,1,'Desiccation is?',['the removal or loss of moisture','the addition of water to a dry material','the freezing of a liquid'],'the removal or loss of moisture','Desiccation means thorough drying.'),Q('desiccation',2,1,'Which process involves desiccation?',['Drying herbs until little moisture remains.','Soaking raisins until they swell.','Adding water to soup.'],'Drying herbs until little moisture remains.','The herbs lose moisture as they dry.'),Q('desiccation',3,1,'The desiccation of soil during a drought leaves it?',['very dry','fully flooded','covered with fresh snow'],'very dry','Desiccation is a loss of moisture.'),Q('desiccation',4,1,'A lab studies desiccation of a sample to measure?',['how it dries as moisture is removed','how quickly it gains colour','how loudly it vibrates'],'how it dries as moisture is removed','The term names the drying process.') ]});
D('designation',{etymology:E('Designation comes from Latin designatio, from designare “mark out, appoint,” formed from de- and signare “mark.” It means choosing someone or something for a purpose or assigning an official name.','designation'),contexts:[C('designation.s1','工作任命','Her designation as project lead took effect after the board approved the appointment and announced her responsibilities.','董事会批准任命并公布职责后，她被指定为项目负责人一事正式生效。','Her designation as project lead took effect / after the board approved the appointment and announced her responsibilities.','designation as + 职务表示指定或任命某人担任该职。','董事会批准她担任负责人，对应任命义 s1。'),C('designation.s2','正式名称','The protected-area designation prevents new construction within the wetland and its surrounding buffer zone.','该保护区称号禁止在湿地及其周边缓冲区内新建工程。','The protected-area designation prevents new construction / within the wetland and its buffer zone.','designation 也指官方赋予的名称或称号。','protected-area 是该地获正式指定的身份名称，对应 s2。')],mistakes:[M('Her designation as team captain meant she was formally named captain, but she was not given that title.','Her designation as team captain meant she was formally named captain and given that title.','正式指定为队长却没有获得该称号自相矛盾。')],quiz:[Q('designation',1,1,'A worker’s designation as safety officer means the worker?',['has been chosen for that role','has resigned from every position','has changed the office address'],'has been chosen for that role','This sense is the act of selecting someone for a purpose.'),Q('designation',2,2,'A building receives a heritage designation. It receives?',['an official title or status','a demolition order automatically','a new owner’s personal name'],'an official title or status','Designation can mean an official name or classification.'),Q('designation',3,1,'Which event is a designation?',['The board appoints Mira as treasurer.','A storm damages the roof.','The treasurer submits a receipt.'],'The board appoints Mira as treasurer.','The appointment chooses her for a role.'),Q('designation',4,2,'In “the site’s designation as a nature reserve,” designation refers to?',['its official name or status','the date it was discovered','the scientist who mapped it'],'its official name or status','The phrase names the status assigned to the site.') ]});
D('designer',{etymology:E('Designer is design plus the agent suffix -er. Design came through French from Latin designare “mark out, devise”; designer names a person who plans products or, in another sense, a scheme.','designer'),contexts:[C('designer.s1','工业设计','The furniture designer tested three chair prototypes before choosing a shape that could be assembled without special tools.','家具设计师测试了三种椅子原型，之后选定了无需特殊工具即可组装的形状。','The furniture designer tested three chair prototypes / before choosing a shape that could be assembled easily.','designer 指以设计服装、建筑或产品为职业的人。','规划并测试家具产品体现职业设计师义 s1。'),C('designer.s2','阴谋策划','Investigators traced the forged documents to the scheme’s designer, who had planned how each false signature would appear.','调查人员追查到伪造文件阴谋的策划者，此人预先安排了每个假签名的样子。','Investigators traced the forged documents to the scheme’s designer / who had planned each false signature.','designer 也可指阴谋或计划的策划者，常含贬义。','他设计了欺诈方案和签名，体现策划者义 s2。')],mistakes:[M('The designer of the fraud had no part in planning it and merely discovered the scheme afterward.','The investigator who discovered the fraud had no part in planning it and merely uncovered the scheme afterward.','发现骗局的人不是骗局的策划者；designer 指设计、策划方案的人。','confusable')],quiz:[Q('designer',1,1,'A product designer is responsible for?',['planning the form or function of products','delivering every finished product personally','writing the customer’s tax return'],'planning the form or function of products','A designer plans the form of products, buildings, or clothing.'),Q('designer',2,2,'The designer of a dishonest scheme is the person who?',['planned the scheme','reported it to the police','was deceived by it'],'planned the scheme','The broader sense is a person who devises a plan, sometimes dishonest.'),Q('designer',3,1,'Which person is a designer in the occupational sense?',['Someone who plans the layout of a new kitchen.','Someone who pays for the kitchen.','Someone who cleans the kitchen after dinner.'],'Someone who plans the layout of a new kitchen.','Designing the layout is the professional task.'),Q('designer',4,2,'The scheme’s designer is most likely?',['the person who devised it','the person who dismantled it','the person who unknowingly suffered from it'],'the person who devised it','A designer in this sense is the planner or creator of the scheme.') ]});
D('designing',{etymology:E('Designing is the -ing form of design, from French desseigner and Latin designare “mark out, devise.” As an adjective it can mean cunning and self-serving; as a noun it is the activity of making a design.','designing'),contexts:[C('designing.s1','人物性格','The designing agent offered to help the rival company, while secretly arranging to divert its best clients elsewhere.','这个工于心计的经纪人提出帮助竞争公司，却暗中安排把其最好的客户引向别处。','The designing agent offered to help the rival company / while secretly arranging to divert its best clients.','designing 作形容词，指以狡猾方式谋取私利。','表面帮助、暗中挖走客户体现诡诈义 s1。'),C('designing.s2','产品开发','Designing a safer handle required several rounds of user testing and a change to the material.','设计更安全的把手需要多轮用户测试，并更换材料。','Designing a safer handle required several rounds of user testing / and a change to the material.','designing 作动名词，指规划产品如何制造的活动。','测试和材料选择都是设计工作，对应 s2。')],mistakes:[M('The designing agent openly shared every plan, sought no advantage, and acted with complete honesty.','The honest agent openly shared every plan, sought no advantage, and acted with complete honesty.','坦诚、不谋私利的行为不符合 designing 的诡诈义。')],quiz:[Q('designing',1,1,'A designing person is?',['clever in a dishonest, self-serving way','unable to make any plan','an official who announces a title'],'clever in a dishonest, self-serving way','The adjective means cunning and often implies dishonest planning.'),Q('designing',2,2,'Designing a bridge includes?',['planning how it should be built','checking its history after it is gone','collecting tickets at its entrance'],'planning how it should be built','As a gerund, designing is the activity of planning a structure.'),Q('designing',3,1,'Which character seems designing?',['She secretly plans to take credit for a colleague’s work.','He openly credits everyone who helped.','They ask for feedback before deciding.'],'She secretly plans to take credit for a colleague’s work.','Secretly plotting for personal advantage fits the adjective.'),Q('designing',4,2,'A course in designing furniture teaches students to?',['plan the form and construction of furniture','repair roads','assign official titles'],'plan the form and construction of furniture','The noun/gerund sense is the process of making a design.') ]});
D('desirability',{etymology:E('Desirability is desirable plus -ity. Desirable comes from desire, through Old French desirrer from Latin desiderare; desirability names the quality of being worth wanting or attractive as a goal.','desirability'),contexts:[C('desirability.s1','岗位评估','The desirability of the position increased when the company added flexible hours, paid training, and a clear promotion path.','公司增加弹性工时、带薪培训和明确晋升路径后，这个职位更值得向往了。','The desirability of the position increased / when the company added flexible hours / paid training / and a promotion path.','desirability 指某物作为目标或选择的吸引力、可取性。','福利使职位更有吸引力。')],mistakes:[M('The job’s desirability fell after it gained flexible hours, paid training, and a clear promotion path.','The job’s desirability rose after it gained flexible hours, paid training, and a clear promotion path.','这些福利通常增加职位吸引力，因此不能支撑 desirability 下降。')],quiz:[Q('desirability',1,1,'The desirability of a home refers to?',['how attractive or worth wanting it is','how many letters are in its address','how old its owner is'],'how attractive or worth wanting it is','Desirability is the quality of being desirable.'),Q('desirability',2,1,'Which change may increase a job’s desirability?',['Adding paid leave and flexible hours.','Cutting wages and removing all breaks.','Moving the office without notice.'],'Adding paid leave and flexible hours.','Better conditions can make a position more attractive.'),Q('desirability',3,1,'A buyer compares the desirability of two locations. The buyer compares their?',['relative attractiveness as places to live','number of words in their names','distance from the moon'],'relative attractiveness as places to live','The noun concerns how desirable or attractive each option is.'),Q('desirability',4,1,'The suffix -ity in desirability forms?',['a noun for a quality or state','a past participle','a person who desires'],'a noun for a quality or state','-ity turns desirable into the noun naming its quality.') ]});
D('desirous',{etymology:E('Desirous is desire plus -ous. Desire came through Old French desirrer from Latin desiderare “long for”; the adjective means having a strong wish, commonly in the construction desirous of.','desirous'),contexts:[C('desirous.s1','正式请求','The board was desirous of hearing from residents before it approved the redevelopment plan.','董事会希望在批准改建方案之前听取居民意见。','The board was desirous of hearing from residents / before approving the redevelopment plan.','be desirous of + 名词或动名词，正式地表示渴望。','董事会有强烈意愿先听取意见，符合 s1。'),C('desirous.s2','行动意愿','Several volunteers were desirous to help once they learned that the flood had damaged the village clinic.','得知洪水损坏了村里的诊所后，几位志愿者想要提供帮助。','Several volunteers were desirous to help / after learning the flood had damaged the clinic.','desirous 也可表示想要做某事，后接不定式。','志愿者希望采取行动，对应 s2。')],mistakes:[M('The board was desirous of hearing residents, but it had no wish at all to listen to anyone.','The board was reluctant to hear residents and had no wish to listen to anyone.','desirous 表示有意愿或渴望，与“完全不愿意听”冲突。','confusable')],quiz:[Q('desirous',1,1,'A person desirous of information is?',['eager to obtain it','certain never to need it','already unable to read'],'eager to obtain it','Desirous means having a strong wish for something.'),Q('desirous',2,2,'The volunteers were desirous to help. They?',['wanted to help','refused to help','had already left'],'wanted to help','This use expresses a wish to do something.'),Q('desirous',3,1,'Choose the usual formal pattern.',['desirous of further discussion','desirous at further discussion','desirous for discuss'],'desirous of further discussion','Desirous is commonly followed by of plus a noun or gerund.'),Q('desirous',4,2,'A team desirous to improve its service?',['wants to improve it','has no intention of improving it','has already stopped providing it'],'wants to improve it','Desirous to + verb expresses a wish to do something.') ]});
D('desperately',{etymology:E('Desperately is desperate plus -ly. Desperate came from Latin desperare “lose hope,” formed from de- and sperare “hope”; the adverb can describe hopeless urgency or an extreme degree.','desperately'),contexts:[C('desperately.s1','紧急求助','With the boat taking on water, the passengers desperately waved at a passing ferry and shouted for help.','船开始进水时，乘客们绝望而急切地向经过的渡船挥手并大声求救。','With the boat taking on water / the passengers desperately waved at a passing ferry / and shouted for help.','desperately 描写因希望渺茫而拼命采取行动。','船进水时急切求救体现绝望、拼命义 s1。'),C('desperately.s2','强烈需要','The rural clinic desperately needs a second nurse because its only nurse is covering three villages.','这家乡村诊所急需第二名护士，因为现有的唯一一名护士要照顾三个村庄。','The rural clinic desperately needs a second nurse / because its only nurse covers three villages.','desperately 可作程度副词，意为极其、非常。','人手严重不足，说明迫切需要，符合 s2。')],mistakes:[M('The clinic desperately needed a second nurse, but its staffing was already abundant and no shortage existed.','The clinic no longer desperately needed a second nurse because staffing was abundant and no shortage existed.','人手充足且没有短缺与 desperately needed 相矛盾。')],quiz:[Q('desperately',1,1,'A person desperately signals a boat because the person?',['has little hope and urgently needs help','is calmly describing a holiday','is giving a routine greeting'],'has little hope and urgently needs help','The first sense conveys urgent action born of near hopelessness.'),Q('desperately',2,2,'“We desperately need more clean water” means we need it?',['very much and urgently','only as a decoration','less than before'],'very much and urgently','Desperately can intensify need to mean extremely.'),Q('desperately',3,1,'Which scene best fits desperately?',['A lost hiker waves frantically when a search plane appears.','A relaxed visitor takes notes in a museum.','A chef calmly reads a menu.'],'A lost hiker waves frantically when a search plane appears.','The hiker acts with urgency and little hope of being found.'),Q('desperately',4,2,'The team is desperately short of time. It is?',['extremely short of time','slightly early','unconcerned about the schedule'],'extremely short of time','Here desperately means to a very great degree.') ]});
D('desperation',{etymology:E('Desperation comes from Latin desperatio, from desperare “lose hope,” formed from de- and sperare “hope.” It names a state of hopelessness that may drive someone to extreme action.','desperation'),contexts:[C('desperation.s1','危急选择','In desperation, the stranded hikers left the marked trail to reach a ridge where they hoped a rescue helicopter could see them.','绝望之下，受困的徒步者离开标记路线，爬上山脊，希望救援直升机能看见他们。','In desperation / the stranded hikers left the marked trail / hoping a rescue helicopter could see them.','in desperation 表示因无计可施、希望渺茫而采取行动。','受困者迫切寻找获救机会，体现绝望义。')],mistakes:[M('She acted in desperation because she had many safe options and felt completely certain that nothing could go wrong.','She acted calmly because she had many safe options and felt certain nothing could go wrong.','有许多安全选择且毫无担忧，不符合 desperation 的无望处境。')],quiz:[Q('desperation',1,1,'A person acts in desperation when the person?',['feels there is little hope and may try anything','is completely relaxed with many easy options','has already forgotten the problem'],'feels there is little hope and may try anything','Desperation is intense hopelessness that can prompt extreme action.'),Q('desperation',2,1,'Which situation could lead to desperation?',['Being stranded with no food and no signal.','Having several safe routes home.','Receiving the help one requested.'],'Being stranded with no food and no signal.','A lack of hope and options can create desperation.'),Q('desperation',3,1,'The phrase “out of desperation” suggests an action was taken?',['because no hopeful alternative seemed available','as part of a routine celebration','to prove a mathematical result'],'because no hopeful alternative seemed available','The phrase points to a hopeless or extreme situation.'),Q('desperation',4,1,'Which is closest to desperation?',['hopelessness','prosperity','curiosity'],'hopelessness','Desperation is the state of feeling that hope is gone.') ]});
D('despicable',{etymology:E('Despicable comes from Latin despicabilis “contemptible,” from despicari “look down on with contempt,” related to despicere “look down.” It describes conduct or a person worthy of contempt.','despicable'),contexts:[C('despicable.s1','道德谴责','The judge called the deliberate poisoning of the town’s water supply despicable and imposed the maximum sentence allowed by law.','法官称蓄意毒害镇上供水的行为卑劣可鄙，并依法判处了最高刑罚。','The judge called the deliberate poisoning of the town’s water supply despicable / and imposed the maximum lawful sentence.','despicable 表示坏到令人鄙视、应受强烈谴责。','蓄意危害公众健康的行为极其卑劣，符合 s1。'),C('despicable.s2','人格评价','The memoir portrays the official as despicable because he knowingly framed an innocent aide to protect his own position.','回忆录称这名官员品行恶劣，因为他明知无辜助手清白，却为保住自己的职位而陷害对方。','The memoir portrays the official as despicable / because he framed an innocent aide to protect his position.','despicable 可形容道德上丑恶、毫不值得尊敬的人或行为。','陷害无辜者以自保表现出道德卑劣，对应 s2。')],mistakes:[M('The court praised the despicable act of framing an innocent person as honourable and worthy of respect.','The court condemned the despicable act of framing an innocent person as dishonourable and worthy of contempt.','陷害无辜者不可能因其卑劣本质而成为值得尊敬的行为。')],quiz:[Q('despicable',1,1,'A despicable act is?',['so bad that it deserves contempt','kind and generous','too small to notice'],'so bad that it deserves contempt','Despicable means deserving strong dislike or contempt.'),Q('despicable',2,2,'A despicable official who frames an innocent person is?',['morally unworthy of respect','a neutral witness','a person who has not made a decision'],'morally unworthy of respect','The adjective can describe morally ugly conduct or a person.'),Q('despicable',3,1,'Which action is most plausibly despicable?',['Knowingly endangering a town’s water to gain money.','Returning a lost wallet.','Admitting an honest mistake.'],'Knowingly endangering a town’s water to gain money.','Deliberately harming the public for personal gain deserves contempt.'),Q('despicable',4,2,'Calling someone despicable expresses?',['strong moral contempt','mild uncertainty about the weather','approval of the person’s choices'],'strong moral contempt','The adjective is a severe judgment of someone’s conduct or character.') ]});
D('despoil',{etymology:E('Despoil came through Anglo-French despoiller from Latin despoliare, “strip of clothing or plunder,” from de- and spoliare “rob.” It means rob a place or strip something of its valuables or beauty.','despoil'),contexts:[C('despoil.s1','历史遗址','The invading army despoiled the palace, carrying away its silver vessels and dismantling the carved doors.','入侵军队洗劫了宫殿，带走银器并拆下雕花门板。','The invading army despoiled the palace / carrying away silver vessels and dismantling carved doors.','despoil + 地点/物品表示掠夺其有价值的东西。','银器被带走、门板被拆，体现掠夺义。'),C('despoil.s2','自然景观','The quarry despoiled the hillside of its trees and exposed rock, leaving the landscape scarred.','采石场剥夺了山坡上的树木并使岩石裸露，令景观满目疮痍。','The quarry despoiled the hillside of its trees and exposed rock / leaving the landscape scarred.','despoil someone/something of + 物品，表示剥夺或毁坏其资源、美感。','采石破坏山坡原有景观，对应 s2。')],mistakes:[M('The looters despoiled the museum by returning every stolen object and leaving its collection untouched.','The looters despoiled the museum by stealing its valuable objects and damaging its collection.','归还所有物品且未破坏展品与掠夺破坏的含义相反。')],quiz:[Q('despoil',1,1,'An army despoiled a palace. It?',['robbed it of valuables','restored every damaged room','appointed its caretaker'],'robbed it of valuables','Despoil can mean plunder a place.'),Q('despoil',2,2,'A mine despoiled the valley of its forests. The mine?',['stripped the valley of its trees','planted a forest there','gave the valley a new name'],'stripped the valley of its trees','This sense means strip something of its beauty or resources.'),Q('despoil',3,1,'Which action is despoiling a site?',['Removing its historic objects for private sale.','Cleaning its paths for visitors.','Recording its history in a guidebook.'],'Removing its historic objects for private sale.','Taking valuable objects away is plunder.'),Q('despoil',4,2,'The phrase “despoil the coast of its natural beauty” means?',['damage or strip away that beauty','protect it from development','measure its length'],'damage or strip away that beauty','Despoil can mean deprive a place of its beauty or wealth.') ]});
D('despoiler',{etymology:E('Despoiler is formed from despoil plus the agent suffix -er. Despoil came from Latin despoliare “strip or plunder,” so a despoiler is someone who takes valuables or damages a place.','despoiler'),contexts:[C('despoiler.s1','文物保护','The curator described the smugglers as despoilers of the ancient site because they removed its carved stones for sale.','馆长称走私者是古遗址的掠夺者，因为他们拆走雕刻石块出售。','The curator described the smugglers as despoilers of the ancient site / because they removed carved stones for sale.','despoiler 指掠夺某地或剥夺其珍贵物品的人。','拆走并出售遗址文物体现掠夺者义。')],mistakes:[M('The despoiler protected the ancient site by leaving every artifact in place and preventing theft.','The conservator protected the ancient site by leaving every artifact in place and preventing theft.','保护遗址并阻止偷盗的人是 conservator，不是 despoiler。','confusable')],quiz:[Q('despoiler',1,1,'A despoiler of a historic site is someone who?',['plunders or damages it','restores it carefully','writes its visitor guide'],'plunders or damages it','The noun names a person who despoils a place.'),Q('despoiler',2,1,'Which person is a despoiler?',['A raider who steals temple artifacts.','A conservator who stabilizes a wall.','A guide who explains the site’s history.'],'A raider who steals temple artifacts.','Stealing the artifacts is plunder.'),Q('despoiler',3,1,'The agent suffix -er in despoiler points to?',['the person who despoils','the place being robbed','the past tense of despoil'],'the person who despoils','Despoiler is the person performing the action.'),Q('despoiler',4,1,'A despoiler may strip a landscape of?',['its natural resources or beauty','its calendar dates','its spoken language only'],'its natural resources or beauty','The noun also applies to someone who ravages a landscape.') ]});
D('despondent',{etymology:E('Despondent comes from Latin despondere “promise solemnly, give up,” and developed the sense of losing hope. It describes someone deeply unhappy or lacking spirit.','despondent'),contexts:[C('despondent.s1','比赛失利','After the final appeal was rejected, the despondent runner sat quietly in the locker room and wondered whether to compete again.','最后一次申诉被驳回后，这名沮丧的跑者静静坐在更衣室里，思考是否还要继续参赛。','After the final appeal was rejected / the despondent runner sat quietly / wondering whether to compete again.','despondent 表示不快乐、失去希望。','申诉失败使跑者情绪低落并怀疑未来。'),C('despondent.s2','精神不振','The volunteers looked despondent after hours of searching, their shoulders lowered and their voices growing faint.','志愿者搜寻数小时后显得无精打采，肩膀垂下，声音也越来越低。','The volunteers looked despondent after hours of searching / their shoulders lowered / and voices growing faint.','despondent 也可描述缺乏精神、精力低落的样子。','肢体和声音表现出精神不振。')],mistakes:[M('Although the application was rejected, she felt despondent, celebrating enthusiastically and expecting certain success.','Although the application was accepted, she felt hopeful, celebrating enthusiastically and expecting success.','热烈庆祝并期待成功的情绪与沮丧、无望相反。','confusable')],quiz:[Q('despondent',1,1,'A despondent person feels?',['unhappy and without hope','certain that everything will succeed','eager to start a celebration'],'unhappy and without hope','The main sense is deep unhappiness and loss of hope.'),Q('despondent',2,2,'A despondent team after a long search may appear?',['low in spirit and energy','physically taller','more confident than before'],'low in spirit and energy','This sense emphasizes a lack of spirit or energy.'),Q('despondent',3,1,'Which event could make someone despondent?',['A final attempt to solve a problem fails.','A long-awaited goal is achieved.','A friend brings welcome news.'],'A final attempt to solve a problem fails.','Failure with few remaining options may produce hopelessness.'),Q('despondent',4,2,'Choose the closest description of despondent volunteers.',['They search slowly with lowered voices.','They cheer loudly and run ahead.','They feel fully refreshed and energetic.'],'They search slowly with lowered voices.','Their behaviour shows low spirit and energy.') ]});
D('destined',{etymology:E('Destined is the past participle and adjective of destine, from Latin destinare “make firm, determine.” It describes what is bound to happen or a person or thing intended for a particular destination.','destined'),contexts:[C('destined.s1','未来结果','With steady improvements and a strong final exam, the young scientist seemed destined for a successful research career.','随着稳步进步和优异的期末考试，这位年轻科学家似乎注定会拥有成功的科研生涯。','With steady improvements and a strong final exam / the young scientist seemed destined for a research career.','be destined for + 结果/身份，表示似乎注定会成为或经历某事。','背景暗示其未来很可能进入科研事业。'),C('destined.s2','运输去向','The crates are destined for the northern clinic, where the winter vaccine campaign starts next week.','这些板条箱预定运往北部诊所，那里下周开始冬季疫苗接种。','The crates are destined for the northern clinic / where the vaccine campaign starts next week.','be destined for + 地点，表示预定前往某处。','货物的预定去向是北部诊所。')],mistakes:[M('The crates are destined for the northern clinic, but their delivery address is the southern port and they will never go north.','The crates are destined for the southern port, their actual delivery address.','destined for 所接地点是预定去向，与句中相反地址不能同时成立。','confusable')],quiz:[Q('destined',1,1,'A person destined for leadership is?',['likely or expected to become a leader','forbidden to lead under any circumstance','already travelling to a city'],'likely or expected to become a leader','This sense describes a future that seems settled or likely.'),Q('destined',2,2,'Packages destined for Oslo are?',['intended to be sent to Oslo','already unpacked in Rome','addressed to the sender only'],'intended to be sent to Oslo','Destined for a place means scheduled or intended to go there.'),Q('destined',3,1,'“The discovery was destined to change medicine” suggests it?',['was expected to have that future effect','was delivered to a hospital','had no effect at all'],'was expected to have that future effect','The adjective can describe something regarded as certain to happen.'),Q('destined',4,2,'Which phrase uses destined for to give a shipment’s route?',['The boxes are destined for the island clinic.','The boxes are destined of the island clinic.','The boxes destined under a label.'],'The boxes are destined for the island clinic.','The construction names the intended destination.') ]});
D('destitute',{etymology:E('Destitute comes from Latin destitutus, past participle of destituere “abandon, leave helpless,” from de- and statuere “set up.” It means extremely poor or completely lacking a resource.','destitute'),contexts:[C('destitute.s1','紧急救助','After the fire destroyed their home and savings, the family was left destitute and needed emergency shelter and food.','火灾烧毁了他们的家和积蓄后，这家人陷入赤贫，急需紧急住所和食物。','After the fire destroyed their home and savings / the family was left destitute / needing shelter and food.','destitute 作形容词表示贫困到缺少食物、住所或金钱。','失去家园与积蓄后需要基本救济，符合 s1。'),C('destitute.s2','资源匮乏','The remote station was destitute of medical supplies during the storm, so staff rationed the remaining bandages.','风暴期间这座偏远站点缺乏医疗用品，因此工作人员配给剩余绷带。','The remote station was destitute of medical supplies / so staff rationed the remaining bandages.','be destitute of + 资源，表示完全缺乏。','医疗物资几乎没有，对应缺乏义 s2。')],mistakes:[M('The destitute family had abundant savings, several secure homes, and more food than it could use.','The prosperous family had abundant savings, several secure homes, and more food than it could use.','拥有充足财富和住房不符合 destitute 的赤贫义。','confusable')],quiz:[Q('destitute',1,1,'A destitute family may lack?',['food, shelter, and money','any need for assistance','a reason to own property'],'food, shelter, and money','Destitute means extremely poor and without basic necessities.'),Q('destitute',2,2,'“The clinic was destitute of medicine” means it?',['had none or almost none','had more medicine than it needed','had just opened a pharmacy'],'had none or almost none','Destitute of means completely lacking something.'),Q('destitute',3,1,'Which circumstance could leave someone destitute?',['Losing home and savings with no support.','Receiving a secure income and housing.','Winning a fully funded scholarship.'],'Losing home and savings with no support.','The loss of basic resources can cause extreme poverty.'),Q('destitute',4,2,'Which is a natural use of destitute of?',['destitute of reliable information','destitute to reliable information','destitute at reliable information'],'destitute of reliable information','The adjective can take of to name what is lacking.') ]});
D('destructive',{etymology:E('Destructive comes from destroy plus -ive; destroy derives from Old French destruire and Latin destruere “tear down,” from de- and struere “build.” The adjective means causing serious damage or harm.','destructive'),contexts:[C('destructive.s1','风暴损害','The destructive storm tore roofs from houses and knocked out power across the coastal district.','这场破坏性风暴掀掉了房屋屋顶，并使沿海地区大范围停电。','The destructive storm tore roofs from houses / and knocked out power across the coastal district.','destructive 修饰 storm，表示造成重大损害。','屋顶损毁与停电体现造成损害义。'),C('destructive.s2','批评方式','Her feedback was destructive rather than helpful because it attacked the junior designer personally and offered no practical suggestions.','她的反馈具有伤害性而非帮助性，因为她人身攻击初级设计师，却没有提供实际建议。','Her feedback was destructive rather than helpful / because it attacked the designer personally / and offered no suggestions.','destructive 可形容有害、打击性的言论或行为。','人身攻击且无建设性建议，符合 s2。')],mistakes:[M('The destructive storm caused no damage at all and left every roof and power line untouched.','The harmless storm caused no damage and left every roof and power line untouched.','毫无损害不符合 destructive 的“造成重大破坏”含义。')],quiz:[Q('destructive',1,1,'A destructive fire is one that?',['causes serious damage','helps repair a building','lasts only one second without effects'],'causes serious damage','Destructive means causing great damage.'),Q('destructive',2,2,'Destructive criticism is criticism that?',['harms rather than helps','offers precise useful guidance','describes a neutral fact only'],'harms rather than helps','This sense describes criticism that is damaging rather than constructive.'),Q('destructive',3,1,'Which event is destructive?',['A flood washes away the road and homes.','A light rain waters a garden.','A repair crew replaces a loose tile.'],'A flood washes away the road and homes.','The flood causes substantial physical damage.'),Q('destructive',4,2,'A destructive argument between colleagues is likely to?',['damage trust without solving the issue','clarify the problem and build trust','measure the room’s width'],'damage trust without solving the issue','The figurative use describes harmful interaction.') ]});
D('destructor',{etymology:E('Destructor comes from Latin destructor, an agent noun from destruere “tear down.” English uses it for a refuse-incineration plant and for a device that destroys a missile or craft if it fails.','destructor'),contexts:[C('destructor.s1','城市垃圾处理','The municipality replaced its old destructor with a modern waste-to-energy incinerator that met stricter emissions limits.','市政府用一座符合更严格排放标准的现代垃圾焚化发电厂，替换了旧焚化炉。','The municipality replaced its old destructor / with a modern waste-to-energy incinerator.','英式或旧式用法中 destructor 可指垃圾焚化炉或焚化厂。','市政垃圾焚化设施对应名词义 s1。'),C('destructor.s2','飞行安全','A test rocket includes a destructor that range staff can activate if the vehicle leaves its approved flight path.','试验火箭装有自毁装置，如果飞行器偏离批准路线，靶场人员可以启动它。','A test rocket includes a destructor / that staff can activate if it leaves its approved flight path.','特定航空航天语境中，destructor 是故障时摧毁飞行器的装置。','火箭偏航时触发自毁装置，对应 s2。')],mistakes:[M('The rocket’s destructor keeps the vehicle intact after it leaves the safe flight corridor.','The rocket’s guidance system keeps the vehicle on course within the safe flight corridor.','destructor 的功能是必要时摧毁飞行器，并非让它保持完整。','confusable')],quiz:[Q('destructor',1,1,'A municipal destructor was historically used to?',['burn refuse','store drinking water','sort library books'],'burn refuse','Destructor can name a refuse-burning plant or furnace.'),Q('destructor',2,2,'A rocket’s destructor may be activated to?',['destroy the vehicle if it goes dangerously off course','refuel it in midair','open its landing gear'],'destroy the vehicle if it goes dangerously off course','This technical sense is a device for destroying a missile or craft.'),Q('destructor',3,1,'Which facility is a destructor in the older municipal sense?',['A furnace that burns the city’s refuse.','A warehouse storing new furniture.','A station that repairs buses.'],'A furnace that burns the city’s refuse.','The historical noun refers to a refuse incinerator.'),Q('destructor',4,2,'A range safety officer uses a destructor when a test craft?',['must be destroyed after a dangerous failure','needs a new paint colour','has landed safely as planned'],'must be destroyed after a dangerous failure','The device is intended to destroy the craft in an emergency.') ]});
D('detached',{etymology:E('Detached is the past participle and adjective of detach, from French détacher, “unfasten, separate.” It can describe physical separation or an impartial, emotionally uninvolved manner.','detached'),contexts:[C('detached.s1','客观观察','The editor took a detached view of the dispute, checking the documents before deciding which account was supported.','编辑以冷静客观的态度看待争议，先核查文件再判断哪种说法有依据。','The editor took a detached view of the dispute / checking the documents before deciding.','detached 描述不受个人情感左右的客观态度。','先看证据而非卷入情绪，符合 s1。'),C('detached.s2','建筑结构','The garage is detached from the house, so visitors reach it by crossing the short path through the garden.','车库与住宅分开，因此访客要穿过花园里的短道才能到达。','The garage is detached from the house / so visitors cross a short path through the garden.','detached from 表示与原本可能相连的事物分离；也可指独立式建筑。','车库和住宅不是相连结构，体现 s2。')],mistakes:[M('The detached garage shares a wall and a doorway with the house as one continuous structure.','The attached garage shares a wall and a doorway with the house as one continuous structure.','共墙相连的车库是 attached，不是 detached。','confusable')],quiz:[Q('detached',1,1,'A detached assessment of a dispute is?',['calm and not personally involved','angry and partisan','physically connected to a wall'],'calm and not personally involved','This sense describes emotional distance and objectivity.'),Q('detached',2,2,'A detached house is?',['separate from other buildings','inside a larger apartment block','a building with no entrance'],'separate from other buildings','Detached can describe a building standing alone.'),Q('detached',3,1,'Which person remains detached while reviewing a complaint?',['A reviewer checks evidence without taking sides.','A reviewer shouts at one party.','A reviewer refuses to read the complaint.'],'A reviewer checks evidence without taking sides.','An impartial, uninvolved approach is detached.'),Q('detached',4,2,'The label became detached from the box. It?',['came loose and separated','was printed more clearly','grew larger'],'came loose and separated','The physical sense means no longer attached.') ]});
D('detachment',{etymology:E('Detachment is detach plus -ment. Detach came through French détacher “unfasten”; detachment can mean emotional impartiality or a group sent away on a separate task.','detachment'),contexts:[C('detachment.s1','新闻报道','She described the conflict with detachment, separating confirmed facts from rumours and avoiding emotional language.','她冷静客观地描述了冲突，将已证实的事实与传言区分开，并避免情绪化语言。','She described the conflict with detachment / separating confirmed facts from rumours / and avoiding emotional language.','with detachment 表示不卷入情绪、保持客观。','区分证据与传言且避免情绪化，体现 s1。'),C('detachment.s2','执行任务','A small police detachment was sent to the island to help local officers secure the port during the festival.','一支小型警察分遣队被派往岛上，在节日期间协助当地警员守卫港口。','A small police detachment was sent to the island / to help local officers secure the port.','detachment 也指被派往执行独立任务的小队。','警察小队被派往外地执行特别任务，对应 s2。')],mistakes:[M('The detached police detachment remained at its original station and no members were sent on a separate assignment.','The police unit remained at its original station and no members were sent on a separate assignment.','没有人员被派出执行独立任务时，不适合称为分遣队。','confusable')],quiz:[Q('detachment',1,1,'A reporter writes with detachment when the reporter?',['remains impartial and emotionally uninvolved','supports one side without checking facts','leaves the news organization'],'remains impartial and emotionally uninvolved','Detachment can mean a calm lack of personal involvement.'),Q('detachment',2,2,'A military detachment is?',['a group sent on a separate task','a single piece of clothing','a public election'],'a group sent on a separate task','This noun also names a separate unit of soldiers or police.'),Q('detachment',3,1,'Which response shows detachment?',['She checks both accounts before reaching a conclusion.','He insults one witness before listening.','They destroy the evidence.'],'She checks both accounts before reaching a conclusion.','Careful impartiality illustrates the emotional sense.'),Q('detachment',4,2,'A detachment of firefighters arrives from another town. It is?',['a group assigned to help at the incident','a chemical used to extinguish flames','a building permit'],'a group assigned to help at the incident','The noun can name a unit assigned to a particular task.') ]});
D('detectable',{etymology:E('Detectable is detect plus -able. Detect comes from Latin detegere “uncover,” from de- and tegere “cover”; detectable describes something that can be noticed or found by a test.','detectable'),contexts:[C('detectable.s1','感官观察','At first there was no detectable change in the colour of the solution, but a faint blue tint appeared after several minutes.','起初溶液的颜色没有可察觉的变化，但几分钟后出现了淡蓝色。','At first there was no detectable change in the colour of the solution / but a faint blue tint later appeared.','detectable 表示可通过感官或仪器察觉到。','颜色变化起初微弱到无法观察，符合 s1。'),C('detectable.s2','医学检测','The screening test found no detectable trace of the virus in the sample, although the patient was tested again a week later.','筛查未在样本中检出病毒痕迹，不过患者一周后又接受了复测。','The screening test found no detectable trace of the virus in the sample / although testing was repeated a week later.','检测语境中 detectable 表示含量足以被测试发现。','检测未发现可检出的病毒量，体现 s2。')],mistakes:[M('The instrument found a detectable signal, yet the signal was impossible for the instrument to register.','The instrument found no detectable signal because it was impossible to register.','被仪器发现的信号必然至少可被该仪器检出。')],quiz:[Q('detectable',1,1,'A detectable sound is one that?',['can be heard or noticed','is guaranteed to be silent','has no measurable existence'],'can be heard or noticed','Detectable means able to be noticed by the senses or an instrument.'),Q('detectable',2,2,'A chemical is present at a detectable level when?',['the test can find it','it is below every test’s sensitivity','it has been removed entirely'],'the test can find it','This sense concerns an amount that a test can register.'),Q('detectable',3,1,'Which change is detectable?',['A sensor records a measurable rise in temperature.','No instrument responds at all.','The sample has been discarded before testing.'],'A sensor records a measurable rise in temperature.','A measurable signal can be detected.'),Q('detectable',4,2,'A lab reports “no detectable amount” of a substance. This means?',['the test did not find a measurable amount','the substance was definitely added','the test found a very high concentration'],'the test did not find a measurable amount','Detectable refers to the test’s ability to find the substance.') ]});
D('detection',{etymology:E('Detection is detect plus -ion. Detect came from Latin detegere “uncover,” from de- and tegere “cover”; detection is discovering something hidden or using equipment to locate it.','detection'),contexts:[C('detection.s1','调查取证','Early detection of the leak allowed the crew to repair the pipe before water reached the archive below.','及时发现泄漏让工作人员在水流到下方档案室之前修好了管道。','Early detection of the leak allowed the crew to repair the pipe / before water reached the archive.','detection 指发现不明显或隐藏的事物。','及时发现隐蔽的泄漏，体现 s1。'),C('detection.s2','雷达设备','The radar system improved detection of small aircraft by filtering out reflections from nearby buildings.','雷达系统通过滤除附近建筑的反射信号，提高了对小型飞机的探测能力。','The radar system improved detection of small aircraft / by filtering out reflections from buildings.','detection 也指使用仪器寻找信号或目标。','雷达设备发现飞机目标，对应 s2。')],mistakes:[M('Early detection of the leak occurred only after the archive had been flooded and the damage was complete.','Late detection of the leak occurred only after the archive had been flooded and the damage was complete.','损害完成后才发现不属于 early detection。','confusable')],quiz:[Q('detection',1,1,'Early detection of a problem means?',['discovering it before it becomes obvious or severe','ignoring it until it disappears','making it more difficult to find'],'discovering it before it becomes obvious or severe','Detection is the discovery of something not obvious.'),Q('detection',2,2,'Radar detection is the use of equipment to?',['find a signal or object','repair a broken road','record a person’s opinion'],'find a signal or object','This sense involves instruments locating a target.'),Q('detection',3,1,'A smoke alarm improves detection of?',['a fire starting in a building','the building’s paint colour','the age of a roof'],'a fire starting in a building','The alarm helps discover a hidden or developing fire.'),Q('detection',4,2,'A metal detector helps with detection by?',['locating metal objects','measuring a person’s height','removing every metal object'],'locating metal objects','The instrument is used to find objects that may be hidden.') ]});
D('determinant',{etymology:E('Determinant comes from determine plus -ant. Determine derives from Latin determinare “set bounds, decide”; determinant can mean a factor that controls an outcome or, as an adjective, something decisive.','determinant'),contexts:[C('determinant.s1','健康研究','Researchers found that access to clean water was a major determinant of child health in the rural districts they studied.','研究人员发现，在所研究的乡村地区，获得清洁饮水是影响儿童健康的重要因素。','Researchers found that access to clean water was a major determinant of child health / in the rural districts.','determinant 作名词指强烈影响结果的因素。','清洁饮水显著影响健康结果，对应 s1。'),C('determinant.s2','关键因素','The deciding goal proved determinant in the final match, fixing the outcome before either team could score again.','这粒制胜球成为决赛的决定性因素，在双方都未能再次得分前锁定了结果。','The deciding goal proved determinant in the final match / fixing the outcome before another score.','determinant 作形容词表示有决定作用的。','进球确定了最终胜负，体现 s2。')],mistakes:[M('The determinant of the crop yield had no effect on it and could not influence the harvest in any way.','The determinant of the crop yield strongly affected it and influenced the harvest.','determinant 是影响结果的因素，完全没有影响的事物不符合该义。')],quiz:[Q('determinant',1,1,'A determinant of exam performance is?',['a factor that strongly affects the result','a page number in the textbook only','a student’s unrelated hobby'],'a factor that strongly affects the result','As a noun, determinant means a factor controlling an outcome.'),Q('determinant',2,2,'A determinant decision is?',['decisive in fixing what happens','irrelevant to the outcome','made after the outcome is forgotten'],'decisive in fixing what happens','The adjective means having the power to decide or fix something.'),Q('determinant',3,1,'Researchers study the determinants of health to identify?',['factors that shape health outcomes','the colours of hospital walls only','the names of patients'],'factors that shape health outcomes','Determinants are influences on an outcome.'),Q('determinant',4,2,'A determinant vote in parliament is one that?',['decides the result','has no effect on the decision','counts only as a rehearsal'],'decides the result','The adjective describes something decisive.') ]});
D('determinedly',{etymology:E('Determinedly is determined plus -ly. Determine came from Latin determinare “set bounds, decide”; determinedly describes acting with firm intention and persistence.','determinedly'),contexts:[C('determinedly.s1','持续训练','Despite the rain, the runners determinedly completed the final set of drills before leaving the track.','尽管下着雨，跑者们仍坚定地完成了最后一组训练才离开跑道。','Despite the rain / the runners determinedly completed the final drills / before leaving the track.','determinedly 修饰 completed，强调坚定意志和不轻言放弃。','即使天气不好仍完成训练，体现坚持的方式。')],mistakes:[M('She determinedly abandoned the rescue search at the first small setback and refused to continue.','She reluctantly abandoned the rescue search at the first small setback and refused to continue.','一遇小挫折就放弃不体现 determinedly 所表达的坚定持续。')],quiz:[Q('determinedly',1,1,'Someone works determinedly toward a goal by?',['persisting with firm intention','quitting as soon as work begins','waiting without making any effort'],'persisting with firm intention','Determinedly means with fixed intention and refusal to stop.'),Q('determinedly',2,1,'Which sentence uses determinedly correctly?',['She determinedly practised until she mastered the piece.','She determinedly gave up before opening the book.','She determinedly was a blue chair.'],'She determinedly practised until she mastered the piece.','Persistent practice shows firm resolve.'),Q('determinedly',3,1,'A rescue team searches determinedly through the night. It searches?',['with persistence and a clear purpose','only for entertainment','without trying to find anyone'],'with persistence and a clear purpose','The adverb describes sustained, purposeful effort.'),Q('determinedly',4,1,'Which is closest in meaning to determinedly?',['resolutely','carelessly','accidentally'],'resolutely','Both words describe firm, purposeful persistence.') ]});
D('determinism',{etymology:E('Determinism is determine plus -ism. Determine derives from Latin determinare “set bounds”; the philosophical doctrine holds that events are fully caused by prior conditions.','determinism'),contexts:[C('determinism.s1','哲学讨论','The seminar compared determinism with theories that allow genuine alternative choices, asking whether every action follows from prior causes.','研讨会将决定论与允许真实替代选择的理论作比较，讨论每个行动是否都由先前原因决定。','The seminar compared determinism with theories that allow alternative choices / asking whether actions follow from prior causes.','determinism 是认为事件由先前条件完全决定的学说。','研讨会讨论因果是否决定所有行动，体现哲学义。')],mistakes:[M('Determinism claims that events have no causes and occur wholly independently of earlier conditions.','Indeterminism claims that events are not wholly fixed by earlier conditions.','determinism 的核心恰是事件由先前条件造成，而非无因发生。','confusable')],quiz:[Q('determinism',1,1,'Determinism is the belief that events?',['are fully caused by prior conditions','occur without any causes','are decided only by tomorrow’s weather'],'are fully caused by prior conditions','The doctrine holds that earlier conditions determine what happens.'),Q('determinism',2,1,'A debate about determinism may ask whether?',['every choice follows from prior causes','gravity exists only in stories','all events happen in reverse'],'every choice follows from prior causes','Determinism concerns causal determination of events.'),Q('determinism',3,1,'Which statement expresses determinism?',['Given the same prior conditions, the outcome is fixed.','Nothing that happens has any cause.','The past is created by future events.'],'Given the same prior conditions, the outcome is fixed.','The position treats prior conditions as determining the result.'),Q('determinism',4,1,'The suffix -ism in determinism commonly marks?',['a doctrine or system of belief','a person who performs a task','a location'],'a doctrine or system of belief','Determinism names a philosophical doctrine.') ]});
D('deterrence',{etymology:E('Deterrence is deter plus -ence. Deter comes from Latin deterrere, “frighten off,” from de- and terrere “frighten”; deterrence is discouraging action through a threatened consequence.','deterrence'),contexts:[C('deterrence.s1','法律威慑','The judge said a visible penalty was intended to provide deterrence by discouraging other drivers from speeding near the school.','法官表示，明确的处罚旨在形成威慑，阻止其他司机在学校附近超速。','The judge said a visible penalty was intended to provide deterrence / by discouraging speeding near the school.','deterrence 指通过威胁惩罚来制止不希望发生的行为。','处罚旨在阻止他人超速，符合威慑义。')],mistakes:[M('The penalty was designed for deterrence, but it encouraged more drivers to speed and removed any reason to obey the limit.','The penalty failed as deterrence because it encouraged more drivers to speed and removed any reason to obey the limit.','若处罚反而鼓励违规，就没有起到制止作用。')],quiz:[Q('deterrence',1,1,'Deterrence aims to?',['discourage an unwanted action through threatened consequences','reward the action it seeks to stop','hide all rules from the public'],'discourage an unwanted action through threatened consequences','Deterrence uses the prospect of punishment to prevent behaviour.'),Q('deterrence',2,1,'A lock may provide deterrence by?',['making a break-in seem riskier','making the door disappear','guaranteeing that no one owns a key'],'making a break-in seem riskier','A visible barrier can discourage an attempted crime.'),Q('deterrence',3,1,'A deterrence policy is judged partly by whether it?',['reduces the behaviour it targets','increases that behaviour','changes the spelling of the law'],'reduces the behaviour it targets','The purpose is to discourage an unwanted action.'),Q('deterrence',4,1,'The noun deterrence is related to the verb?',['deter','deliver','detour'],'deter','Deter means frighten or discourage someone from acting.') ]});
D('deterrent',{etymology:E('Deterrent comes from Latin deterrere “frighten away,” from de- and terrere “frighten,” with the agent/adjective suffix -ent. It names something that discourages an action or describes a discouraging effect.','deterrent'),contexts:[C('deterrent.s1','购物决策','The high cost of parking was a deterrent to visitors, so many chose the train instead.','高昂的停车费让游客望而却步，因此许多人改乘火车。','The high cost of parking was a deterrent to visitors / so many chose the train instead.','a deterrent to + 行为/对象，指令人不愿采取行动的因素。','停车费让人放弃开车前往，对应名词义 s1。'),C('deterrent.s2','法律政策','The city introduced deterrent fines for dumping rubbish in the river, hoping the risk of a large penalty would stop repeat offences.','市政府对向河里倾倒垃圾的行为设立了有威慑力的罚款，希望高额处罚能制止再犯。','The city introduced deterrent fines for dumping rubbish / hoping the risk of a large penalty would stop repeat offences.','deterrent 作形容词表示旨在制止不当行为的。','罚款被设置来阻止违法行为，符合 s2。')],mistakes:[M('The fine was a deterrent to illegal dumping because it made offenders more eager to dump waste again.','The fine failed as a deterrent to illegal dumping because it made offenders more eager to repeat it.','如果罚款反而促使人再犯，它就没有起到 deterrent 的制止作用。')],quiz:[Q('deterrent',1,1,'A deterrent to theft is?',['something that discourages theft','a reward for stealing','a record of stolen property'],'something that discourages theft','As a noun, deterrent is something that makes an action less attractive.'),Q('deterrent',2,2,'A deterrent penalty is intended to?',['discourage people from breaking a rule','reward every violation','erase the rule from the book'],'discourage people from breaking a rule','The adjective means intended to discourage an unwanted action.'),Q('deterrent',3,1,'High ticket prices can be a deterrent to attendance because they?',['make people less likely to go','provide free entry','increase the number of seats'],'make people less likely to go','The cost discourages attendance.'),Q('deterrent',4,2,'Which phrase uses deterrent adjectivally?',['deterrent measures','a deterrent to visitors','the deterrent was costly'],'deterrent measures','Here deterrent modifies measures, describing their intended effect.') ]});
D('dethrone',{etymology:E('Dethrone is de- plus throne. Throne came through French from Latin thronus and Greek thronos; dethrone means remove a ruler from power or figuratively take a leading position from a rival.','dethrone'),contexts:[C('dethrone.s1','君主更替','The revolution dethroned the monarch and established an elected assembly in the former royal capital.','革命废黜了君主，并在原来的王都建立了民选议会。','The revolution dethroned the monarch / and established an elected assembly.','dethrone 作及物动词，指把君主或类似统治者赶下台。','君主失去王位并由新政体取代，对应 s1。'),C('dethrone.s2','市场竞争','A smaller company hopes to dethrone the market leader by offering a cheaper battery with twice the range.','一家规模较小的公司希望凭借价格更低、续航翻倍的电池取代市场领先者。','A smaller company hopes to dethrone the market leader / with a cheaper battery offering twice the range.','dethrone 可比喻取代某人或产品的领先地位。','公司要取代市场冠军，对应 s2。')],mistakes:[M('The revolution dethroned the monarch by restoring the monarch to full power and leaving the throne unchanged.','The revolution dethroned the monarch by removing the monarch from power.','恢复君主权力与 dethrone（废黜）意思相反。','confusable')],quiz:[Q('dethrone',1,1,'To dethrone a king is to?',['remove him from power','give him a new crown while keeping him ruler','elect him for another term'],'remove him from power','The literal sense is to remove a monarch from the throne.'),Q('dethrone',2,2,'A new phone may dethrone the current bestseller by?',['taking its leading sales position','removing its physical crown','repairing its screen'],'taking its leading sales position','Figuratively, dethrone means take the leading place from a rival.'),Q('dethrone',3,1,'Which historical event could dethrone a ruler?',['A successful revolution removes the monarch.','The monarch attends a parade.','A royal portrait is repainted.'],'A successful revolution removes the monarch.','The ruler loses power, which is the literal sense.'),Q('dethrone',4,2,'“The challenger dethroned the champion” means the challenger?',['took the champion’s leading position','built a palace for the champion','refused to compete'],'took the champion’s leading position','The figurative use is to replace someone at the top.') ]});
D('detour',{etymology:E('Detour came through French détour from détourner “turn aside,” based on tourner “turn.” As a noun it is a longer alternative route; as a verb it means travel by such a route.','detour'),contexts:[C('detour.s1','道路指引','The roadworks forced a detour through the village, adding twenty minutes to the journey.','道路施工迫使车辆绕经村庄，使行程多花了二十分钟。','The roadworks forced a detour through the village / adding twenty minutes to the journey.','a detour 是比直接道路更长的替代路线。','施工让车辆改走更长路线，对应 s1。'),C('detour.s2','绕行路线','Drivers should detour around the flooded bridge and follow the signed route on the east bank.','司机应绕开被淹的桥，沿东岸的标示路线行驶。','Drivers should detour around the flooded bridge / and follow the signed route on the east bank.','detour 可作动词，表示绕道行驶。','司机需要改走其他路线，对应 s2。')],mistakes:[M('The road was closed, so drivers took a detour that followed the same blocked bridge and added no alternative route.','The road was closed, so drivers took a detour around the blocked bridge by an alternative route.','绕道必须避开封闭路段；仍走同一座封桥并非 detour。')],quiz:[Q('detour',1,1,'A detour is?',['a longer alternative route','the shortest direct street','a vehicle’s fuel tank'],'a longer alternative route','The noun means a way longer than the direct route.'),Q('detour',2,2,'If drivers detour around a flood, they?',['take a different route to avoid it','drive straight through deep water','stop travelling forever'],'take a different route to avoid it','As a verb, detour means go by a longer or alternative route.'),Q('detour',3,1,'A sign reading “Detour” usually tells drivers?',['the usual road is blocked and another route is provided','the destination has moved','their car needs a new engine'],'the usual road is blocked and another route is provided','A detour redirects traffic around an obstruction.'),Q('detour',4,2,'Choose the natural use of detour as a verb.',['We detoured around the flooded underpass.','We detour the bridge into a hill.','We detoured of the bridge.'],'We detoured around the flooded underpass.','Detour around + obstacle is a natural verb pattern.') ]});
D('detract',{etymology:E('Detract comes from Latin detrahere “draw away, take from,” from de- and trahere “pull.” It means reduce the value or attractiveness of something or draw attention away from it.','detract'),contexts:[C('detract.s1','作品评价','A few spelling errors detract from an otherwise persuasive report, making the final draft seem less polished.','几处拼写错误削弱了这份原本有说服力的报告，使最终稿显得不够完善。','A few spelling errors detract from an otherwise persuasive report / making the final draft seem less polished.','detract from + 事物，表示减损其价值、吸引力或效果。','拼写错误使报告不够完善，体现 s1。'),C('detract.s2','注意力转移','The bright logo on the cover detracts from the photograph by drawing the viewer’s attention away from the subject.','封面上鲜艳的标志把观众的注意力从主体上引开，削弱了照片的效果。','The bright logo on the cover detracts from the photograph / by drawing attention away from its subject.','detract from 可指把注意力从某事物上转移开。','标志吸引视线，分散了对照片主体的注意，对应 s2。')],mistakes:[M('The logo detracted from the photograph by making viewers focus more closely on its main subject.','The logo enhanced the photograph by making viewers focus more closely on its main subject.','让观众更关注主体并增强效果，不是把注意力移开的 detract。','confusable')],quiz:[Q('detract',1,1,'Small errors can detract from a report by?',['making it seem less effective or polished','adding evidence to strengthen it','changing its topic to another subject'],'making it seem less effective or polished','Detract from means reduce value or attractiveness.'),Q('detract',2,2,'A loud advertisement may detract from a speech by?',['drawing listeners’ attention away','making every word easier to hear','increasing the speaker’s height'],'drawing listeners’ attention away','This sense is to distract attention from something.'),Q('detract',3,1,'Which sentence uses detract from to mean diminish?',['The scratch detracts from the table’s appearance.','The table detracts from the scratch into wood.','The scratch detracts at the table.'],'The scratch detracts from the table’s appearance.','The scratch makes the table less attractive.'),Q('detract',4,2,'What does “the flashing banner detracts from the map” suggest?',['It distracts viewers from the map.','It improves the map’s legibility.','It describes the map’s scale.'],'It distracts viewers from the map.','The banner pulls attention away from the map.') ]});
D('detraction',{etymology:E('Detraction is detract plus -ion, from Latin detrahere “draw away, take from.” It refers especially to remarks that diminish another person’s reputation.','detraction'),contexts:[C('detraction.s1','声誉维护','The manager rejected the detraction of her colleague as lazy, pointing to his record of completing every urgent assignment.','经理反驳了对同事懒惰的贬低说法，并指出他一直完成每项紧急任务。','The manager rejected the detraction of her colleague as lazy / pointing to his record of completing urgent assignments.','detraction 指损害某人名誉或价值的批评言辞。','经理反对贬损同事的评价，体现 s1。')],mistakes:[M('The detraction of her reputation consisted of accurate public praise that strengthened everyone’s respect for her.','The enhancement of her reputation consisted of accurate public praise that strengthened everyone’s respect for her.','增强声誉的赞扬不是损害名声的 detraction。','confusable')],quiz:[Q('detraction',1,1,'Detraction from someone’s reputation consists of?',['remarks that diminish that person’s standing','evidence that clears the person’s name','a formal promotion'],'remarks that diminish that person’s standing','Detraction refers to comments that damage a reputation.'),Q('detraction',2,1,'A writer avoids detraction by avoiding?',['unfair remarks that lower another person’s reputation','accurate citations','balanced evidence'],'unfair remarks that lower another person’s reputation','The noun names disparaging statements.'),Q('detraction',3,1,'Which is an example of detraction?',['A false claim intended to make a colleague look incompetent.','A documented award for the colleague.','A neutral list of the colleague’s duties.'],'A false claim intended to make a colleague look incompetent.','The false attack attempts to harm the colleague’s reputation.'),Q('detraction',4,1,'Detraction is closest to?',['disparagement','appointment','detour'],'disparagement','Both refer to speaking of someone in a way that lowers their reputation.') ]});

})();
